// Reference implementation: SPSC Concurrent Queue (C)
#include <stddef.h>
#include <stdint.h>
#include <stdbool.h>
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <stdatomic.h>

typedef struct {
    atomic_size_t head;
    atomic_size_t tail;
    size_t capacity;
    int64_t *buffer;
} SPSCQueue;

SPSCQueue *queue_new(size_t capacity) {
    SPSCQueue *q = calloc(1, sizeof(SPSCQueue));
    q->capacity = capacity + 1;
    q->buffer = calloc(q->capacity, sizeof(int64_t));
    atomic_init(&q->head, 0);
    atomic_init(&q->tail, 0);
    return q;
}

bool queue_enqueue(SPSCQueue *q, int64_t val) {
    size_t tail = atomic_load(&q->tail);
    size_t next = (tail + 1) % q->capacity;
    if (next == atomic_load(&q->head)) return false;
    q->buffer[tail] = val;
    atomic_store(&q->tail, next);
    return true;
}

bool queue_dequeue(SPSCQueue *q, int64_t *out) {
    size_t head = atomic_load(&q->head);
    if (head == atomic_load(&q->tail)) return false;
    *out = q->buffer[head];
    atomic_store(&q->head, (head + 1) % q->capacity);
    return true;
}

void queue_destroy(SPSCQueue *q) {
    free(q->buffer);
    free(q);
}

int main(void) {
    SPSCQueue *q = queue_new(1000000);
    for (int64_t i = 0; i < 1000000; i++) queue_enqueue(q, i);
    int64_t v;
    for (int i = 0; i < 1000000; i++) queue_dequeue(q, &v);
    queue_destroy(q);
    printf("OK\n");
    return 0;
}

