/**
 * Reference implementation: Hot-Reload Module Loader (C)
 * Systems Arena -- measures execution speed, memory usage, binary size.
 *
 * Real dynamic module loading: every cycle opens a shared library
 * (dlopen -> RTLD_NOW), resolves the exported function (dlsym), calls it
 * 100 times, then hot-reloads (a fresh dlopen replaces the old handle) and
 * unloads it (dlclose). The workload is identical for every language:
 * libc.so.6 / abs, 1000 cycles x 100 calls, deterministic arguments.
 */
#define _POSIX_C_SOURCE 200809L

#include <stdio.h>
#include <time.h>
#include <dlfcn.h>

#define CYCLES 1000
#define CALLS_PER_CYCLE 100
#define MODULE_PATH "libc.so.6"
#define SYMBOL_NAME "abs"

typedef int (*abs_fn)(int);

int main(void) {
    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);

    long long checksum = 0;
    for (int i = 0; i < CYCLES; i++) {
        void *handle = dlopen(MODULE_PATH, RTLD_NOW);
        if (!handle) {
            fprintf(stderr, "dlopen failed: %s\n", dlerror());
            return 1;
        }
        abs_fn fn = (abs_fn)dlsym(handle, SYMBOL_NAME);
        if (!fn) {
            fprintf(stderr, "dlsym failed: %s\n", dlerror());
            dlclose(handle);
            return 1;
        }
        for (int j = 0; j < CALLS_PER_CYCLE; j++) {
            int arg = (i * 31 + j * 17) % 1000 - 500;
            checksum += fn(arg);
        }
        void *fresh = dlopen(MODULE_PATH, RTLD_NOW);
        if (!fresh) {
            fprintf(stderr, "reload dlopen failed: %s\n", dlerror());
            dlclose(handle);
            return 1;
        }
        dlclose(handle);
        dlclose(fresh);
    }

    clock_gettime(CLOCK_MONOTONIC, &end);
    double ms = (double)(end.tv_sec - start.tv_sec) * 1000.0
              + (double)(end.tv_nsec - start.tv_nsec) / 1e6;
    printf("{\"op\":\"hot-reload\",\"cycles\":%d,\"calls\":%d,\"checksum\":%lld,\"time_ms\":%.2f}\n",
           CYCLES, CYCLES * CALLS_PER_CYCLE, checksum, ms);
    return 0;
}

