// Reference implementation: SPSC Concurrent Queue (C++)
// Systems Arena -- lock-free single-producer single-consumer queue.
#include <cstddef>
#include <cstdint>
#include <atomic>
#include <iostream>

class SPSCQueue {
    std::atomic<size_t> head{0};
    std::atomic<size_t> tail{0};
    size_t capacity;
    int64_t *buffer;

public:
    explicit SPSCQueue(size_t cap) : capacity(cap + 1), buffer(new int64_t[cap + 1]{}) {}

    ~SPSCQueue() { delete[] buffer; }

    bool enqueue(int64_t val) {
        size_t t = tail.load(std::memory_order_relaxed);
        size_t next = (t + 1) % capacity;
        if (next == head.load(std::memory_order_acquire)) return false;
        buffer[t] = val;
        tail.store(next, std::memory_order_release);
        return true;
    }

    bool dequeue(int64_t &out) {
        size_t h = head.load(std::memory_order_relaxed);
        if (h == tail.load(std::memory_order_acquire)) return false;
        out = buffer[h];
        head.store((h + 1) % capacity, std::memory_order_release);
        return true;
    }
};

int main() {
    SPSCQueue q(1000000);
    for (int64_t i = 0; i < 1000000; i++) q.enqueue(i);
    int64_t v;
    for (int i = 0; i < 1000000; i++) q.dequeue(v);
    std::cout << "OK\n";
}

