// Reference implementation: TCP Packet Parser (C++)
// Systems Arena -- parses binary TCP headers and measures throughput.
// Measures: execution speed, memory usage, binary size.
#include <cstdint>
#include <cstring>
#include <cstdio>
#include <ctime>

#pragma pack(push, 1)
struct TcpHeader {
    uint16_t src_port;
    uint16_t dst_port;
    uint32_t seq_num;
    uint32_t ack_num;
    uint8_t  data_offset_reserved;
    uint8_t  flags;
    uint16_t window;
    uint16_t checksum;
    uint16_t urgent_ptr;
};
#pragma pack(pop)

inline uint16_t ntoh16(uint16_t v) { return ((v & 0xFF) << 8) | ((v >> 8) & 0xFF); }
inline uint32_t ntoh32(uint32_t v) {
    return ((v & 0xFF) << 24) | ((v & 0xFF00) << 8) | ((v >> 8) & 0xFF00) | ((v >> 24) & 0xFF);
}

int parse_packet(const uint8_t *data, size_t len, TcpHeader &hdr) {
    if (len < 20) return -1;
    std::memcpy(&hdr, data, 20);
    hdr.src_port = ntoh16(hdr.src_port);
    hdr.dst_port = ntoh16(hdr.dst_port);
    hdr.seq_num = ntoh32(hdr.seq_num);
    hdr.ack_num = ntoh32(hdr.ack_num);
    hdr.window = ntoh16(hdr.window);
    hdr.checksum = ntoh16(hdr.checksum);
    hdr.urgent_ptr = ntoh16(hdr.urgent_ptr);
    return 0;
}

uint16_t compute_checksum(const uint8_t *data, size_t len) {
    uint32_t sum = 0;
    for (size_t i = 0; i + 1 < len; i += 2) {
        sum += ((uint16_t)data[i] << 8) | data[i + 1];
    }
    if (len & 1) sum += (uint16_t)data[len - 1] << 8;
    while (sum >> 16) sum = (sum & 0xFFFF) + (sum >> 16);
    return (uint16_t)~sum;
}

int main() {
    clock_t start = clock();
    uint8_t packet[40]{};

    packet[0] = 0x1F; packet[1] = 0x90;
    packet[2] = 0x00; packet[3] = 0x50;
    packet[4] = 0x00; packet[5] = 0x00; packet[6] = 0x00; packet[7] = 0x01;
    packet[8] = 0x00; packet[9] = 0x00; packet[10] = 0x00; packet[11] = 0x00;
    packet[12] = 0x50;
    packet[13] = 0x02;
    packet[14] = 0x7F; packet[15] = 0xFF;
    packet[16] = 0x00; packet[17] = 0x00;
    packet[18] = 0x00; packet[19] = 0x00;

    TcpHeader hdr;
    for (int i = 0; i < 1000000; i++) {
        packet[4] = (i >> 24) & 0xFF;
        packet[5] = (i >> 16) & 0xFF;
        packet[6] = (i >> 8) & 0xFF;
        packet[7] = i & 0xFF;
        uint16_t csum = compute_checksum(packet, 20);
        packet[16] = (csum >> 8) & 0xFF;
        packet[17] = csum & 0xFF;
        parse_packet(packet, 20, hdr);
    }

    double elapsed = (double)(clock() - start) / CLOCKS_PER_SEC * 1000.0;
    std::printf("{\"op\":\"packet-parse\",\"packets\":1000000,\"time_ms\":%.2f,\"pps\":%.0f}\n",
           elapsed, elapsed > 0 ? 1000000000.0 / elapsed : 0);
    return 0;
}

