// Reference implementation: Buddy Memory Allocator (Rust)
// Systems Arena -- measures raw execution speed, memory, binary size.
#![allow(static_mut_refs)]
use std::ptr::NonNull;

const POOL_SIZE: usize = 1 << 20;
const MIN_BLOCK: usize = 64;
const MAX_ORDER: usize = 14;

struct Block {
    free: bool,
    order: usize,
    next: Option<NonNull<Block>>,
}

static mut POOL: [u8; POOL_SIZE] = [0u8; POOL_SIZE];
static mut FREE_LISTS: [Option<NonNull<Block>>; MAX_ORDER + 1] = [None; MAX_ORDER + 1];
static mut INITIALIZED: bool = false;

fn order_for_size(size: usize) -> usize {
    let mut block_size = MIN_BLOCK;
    let mut order = 0;
    while block_size < size + std::mem::size_of::<Block>() && order < MAX_ORDER {
        block_size <<= 1;
        order += 1;
    }
    order
}

unsafe fn split_block(order: usize) -> Option<NonNull<Block>> {
    if order > MAX_ORDER { return None; }
    if let Some(mut block) = FREE_LISTS[order] {
        let b = block.as_mut();
        FREE_LISTS[order] = b.next;
        b.free = false;
        return Some(block);
    }
    if order == MAX_ORDER { return None; }
    let bigger = split_block(order + 1)?;
    let half = MIN_BLOCK << order;
    let buddy_addr = bigger.as_ptr() as usize + half;
    let buddy = buddy_addr as *mut Block;
    (*buddy).free = true;
    (*buddy).order = order;
    (*buddy).next = FREE_LISTS[order];
    FREE_LISTS[order] = NonNull::new(buddy);
    (*bigger.as_ptr()).free = false;
    (*bigger.as_ptr()).order = order;
    Some(bigger)
}

unsafe fn init() {
    if INITIALIZED { return; }
    let root = POOL.as_mut_ptr() as *mut Block;
    (*root).free = true;
    (*root).order = MAX_ORDER;
    (*root).next = None;
    FREE_LISTS[MAX_ORDER] = NonNull::new(root);
    INITIALIZED = true;
}

unsafe fn alloc(size: usize) -> Option<*mut u8> {
    if !INITIALIZED { init(); }
    if size == 0 { return None; }
    let block = split_block(order_for_size(size))?;
    Some((block.as_ptr() as *mut u8).add(std::mem::size_of::<Block>()))
}

unsafe fn free(ptr: *mut u8) {
    if ptr.is_null() { return; }
    let block = (ptr as *mut Block).sub(1);
    (*block).free = true;
    let mut current = &mut *block;
    while current.order < MAX_ORDER {
        let bsize = MIN_BLOCK << current.order;
        let addr = block as usize - POOL.as_ptr() as usize;
        let buddy_addr = addr ^ bsize;
        if buddy_addr + bsize > POOL_SIZE { break; }
        let buddy = POOL.as_ptr().add(buddy_addr) as *mut Block;
        if !(*buddy).free || (*buddy).order != current.order { break; }
        let mut prev = &mut FREE_LISTS[current.order];
        while let Some(p) = *prev {
            if p.as_ptr() == buddy { *prev = (*p.as_ptr()).next; break; }
            prev = &mut (*p.as_ptr()).next;
        }
        current = if addr < buddy_addr { &mut *block } else { &mut *buddy };
        current.order += 1;
    }
    (*current).next = FREE_LISTS[current.order];
    FREE_LISTS[current.order] = NonNull::new(current as *mut Block);
}

fn main() {
    unsafe {
        init();
        let mut ptrs = [std::ptr::null_mut::<u8>(); 10000];
        for i in 0..10000 { ptrs[i] = alloc(64 + (i * 997) % 4096).unwrap_or(std::ptr::null_mut()); }
        for i in (0..10000).step_by(2) { free(ptrs[i]); }
        for i in (0..10000).step_by(2) { ptrs[i] = alloc(128 + (i * 503) % 2048).unwrap_or(std::ptr::null_mut()); }
        for i in 0..10000 { free(ptrs[i]); }
    }
    println!("OK");
}

