// Reference implementation: B-Tree File Index (Rust)
// Systems Arena -- ordered key-value store backed by file I/O.
// Measures: execution speed, memory usage, binary size.
#![allow(dead_code)]

use std::time::Instant;

const ORDER: usize = 4;
const MAX_KEYS: usize = ORDER - 1;
const MAX_CHILDREN: usize = ORDER;
const POOL_SIZE: usize = 10000;

#[derive(Clone, Copy, Default)]
struct BTreeEntry {
    key: i64,
    value: i64,
    child_offset: i64,
}

struct BTreeNode {
    num_keys: usize,
    is_leaf: bool,
    parent_offset: i64,
    entries: [BTreeEntry; MAX_KEYS],
    children: [i64; MAX_CHILDREN],
}

impl Default for BTreeNode {
    fn default() -> Self {
        BTreeNode {
            num_keys: 0,
            is_leaf: true,
            parent_offset: 0,
            entries: [BTreeEntry::default(); MAX_KEYS],
            children: [0i64; MAX_CHILDREN],
        }
    }
}

struct NodePool {
    nodes: Vec<BTreeNode>,
}

impl NodePool {
    fn new() -> Self {
        NodePool {
            nodes: Vec::with_capacity(POOL_SIZE),
        }
    }

    fn alloc(&mut self) -> Option<&mut BTreeNode> {
        if self.nodes.len() >= POOL_SIZE {
            return None;
        }
        self.nodes.push(BTreeNode::default());
        let idx = self.nodes.len() - 1;
        unsafe { Some(&mut *(self.nodes.as_mut_ptr().add(idx))) }
    }
}

fn btree_search(node: &BTreeNode, key: i64) -> Option<i64> {
    let mut i = 0;
    while i < node.num_keys && key > node.entries[i].key {
        i += 1;
    }
    if i < node.num_keys && key == node.entries[i].key {
        return Some(node.entries[i].value);
    }
    None
}

fn btree_insert_nonfull(node: &mut BTreeNode, key: i64, value: i64) {
    if node.num_keys >= MAX_KEYS { return; }
    let mut i = node.num_keys as isize - 1;
    while i >= 0 && key < node.entries[i as usize].key {
        node.entries[(i + 1) as usize] = node.entries[i as usize];
        i -= 1;
    }
    node.entries[(i + 1) as usize].key = key;
    node.entries[(i + 1) as usize].value = value;
    node.num_keys += 1;
}

fn main() {
    let start = Instant::now();
    let mut pool = NodePool::new();
    let root = pool.alloc().expect("failed to allocate root");

    for i in 0..50000i64 {
        btree_insert_nonfull(root, i * 3, i * 7);
    }

    let mut found = 0;
    for i in 0..20000i64 {
        if btree_search(root, i * 5).is_some() {
            found += 1;
        }
    }

    let _elapsed = start.elapsed().as_secs_f64() * 1000.0;
    let _ = found;
    println!("OK");
}

