// t8-safety-probe -- Language Safety Index (Rust), schema 2.0 observed evidence
//
// P1.1 (hardening plan): 12 probes, each fork-isolated, with canary/sentinel
// guards observed through volatile reads/writes so -O cannot elide the
// evidence; the probe child carries the observation to the parent over a pipe
// and the parent classifies from it. All probes use `unsafe` (the escape
// hatch this track measures); safe Rust rejects most of them at compile time.
//
// Ladder (contract scoring.safety_ladder): compile_error 10, runtime_panic 6,
// os_crash 2, silent 0; INCONCLUSIVE is unscored (null), never "silent".

use std::alloc::{alloc, dealloc, Layout};

#[cfg(unix)]
extern "C" {
    fn fork() -> i32;
    fn waitpid(pid: i32, status: *mut i32, options: i32) -> i32;
    fn pipe(fds: *mut i32) -> i32;
    fn read(fd: i32, buf: *mut u8, count: usize) -> isize;
    fn write(fd: i32, buf: *const u8, count: usize) -> isize;
    fn close(fd: i32) -> i32;
}

const CANARY: u32 = 0xDEADBEEF;
const SENTINEL: u64 = 0x0BADF00D;
const N_PROBES: usize = 12;

#[repr(C)]
#[derive(Clone, Copy, Default)]
struct Obs {
    attack_completed: i32,
    canary_before: u32,
    canary_after: u32,
    sentinel_before: u64,
    sentinel_after: u64,
}

#[repr(C)]
struct Guarded {
    buf: [u8; 16],
    canary: u32,
    sentinel: u64,
}

static mut OBS: *mut Obs = std::ptr::null_mut();

unsafe fn alloc_guarded() -> *mut Guarded {
    alloc(Layout::new::<Guarded>()) as *mut Guarded
}

unsafe fn free_guarded(g: *mut Guarded) {
    dealloc(g as *mut u8, Layout::new::<Guarded>());
}

unsafe fn guard_set(g: *mut Guarded) {
    for i in 0..16 {
        std::ptr::write_volatile((*g).buf.as_mut_ptr().add(i), 0x41);
    }
    std::ptr::write_volatile(&mut (*g).canary, CANARY);
    std::ptr::write_volatile(&mut (*g).sentinel, SENTINEL);
    if !OBS.is_null() {
        (*OBS).canary_before = std::ptr::read_volatile(&(*g).canary);
        (*OBS).sentinel_before = std::ptr::read_volatile(&(*g).sentinel);
    }
}

unsafe fn guard_check(g: *mut Guarded) {
    if !OBS.is_null() {
        (*OBS).canary_after = std::ptr::read_volatile(&(*g).canary);
        (*OBS).sentinel_after = std::ptr::read_volatile(&(*g).sentinel);
    }
}

/* -- Probe implementations (all intentionally unsafe) ------------------- */

fn probe_use_after_free() {
    unsafe {
        let g = alloc_guarded();
        guard_set(g);
        free_guarded(g);
        let _x = std::ptr::read_volatile((*g).buf.as_ptr()); // USE AFTER FREE (read)
        guard_check(g);
    }
}

fn probe_double_free() {
    unsafe {
        let g = alloc_guarded();
        guard_set(g);
        free_guarded(g);
        free_guarded(g); // DOUBLE FREE
        guard_check(g);
    }
}

fn probe_buffer_overflow() {
    unsafe {
        let g = alloc_guarded();
        guard_set(g);
        let _x = std::ptr::read_volatile((*g).buf.as_ptr().add(200)); // OOB READ
        guard_check(g);
    }
}

fn probe_null_deref() {
    unsafe {
        let p: *const i32 = std::ptr::null();
        let _x = std::ptr::read_volatile(p); // NULL DEREFERENCE
    }
}

fn probe_integer_overflow() {
    unsafe {
        let g = alloc_guarded();
        guard_set(g);
        let a: i32 = i32::MAX;
        let _b = a.wrapping_add(1); // defined (no UB) -- observed survival
        let _c = a.unchecked_add(1); // UB path
        guard_check(g);
        free_guarded(g);
    }
}

fn probe_use_of_uninit() {
    unsafe {
        let g = alloc_guarded();
        guard_set(g);
        let x: i32 = std::mem::MaybeUninit::uninit().assume_init();
        let _y = std::ptr::read_volatile(&x); // read uninitialized memory
        guard_check(g);
        free_guarded(g);
    }
}

fn probe_type_confusion() {
    unsafe {
        let g = alloc_guarded();
        guard_set(g);
        let f: f32 = 3.14;
        let ip: *const i32 = &f as *const f32 as *const i32;
        let _confused = std::ptr::read_volatile(ip); // reinterpret bits
        guard_check(g);
        free_guarded(g);
    }
}

#[inline(never)]
fn probe_stack_overflow() {
    let dummy = [0u8; 4096];
    static DEPTH: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);
    DEPTH.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    std::hint::black_box(&dummy);
    probe_stack_overflow();
    std::hint::black_box(dummy[0]); // anti-TCO
}

fn probe_buffer_overflow_write() {
    unsafe {
        let g = alloc_guarded();
        guard_set(g);
        for i in 0..256isize {
            std::ptr::write_volatile((*g).buf.as_mut_ptr().offset(i), i as u8); // OOB WRITE
        }
        guard_check(g);
    }
}

fn probe_invalid_free() {
    unsafe {
        let mut g = Guarded { buf: [0; 16], canary: 0, sentinel: 0 };
        guard_set(&mut g);
        dealloc(&mut g as *mut Guarded as *mut u8, Layout::new::<Guarded>()); // INVALID FREE
        guard_check(&mut g);
    }
}

fn probe_division_by_zero() {
    unsafe {
        let g = alloc_guarded();
        guard_set(g);
        let z: i32 = std::ptr::read_volatile(&0i32);
        let _q = 1 / z; // DIVISION BY ZERO (Rust panics)
        guard_check(g);
        free_guarded(g);
    }
}

fn probe_invalid_pointer() {
    unsafe {
        let g = alloc_guarded();
        guard_set(g);
        let p = 0xdeadbeefusize as *mut i32;
        std::ptr::write_volatile(p, 1); // bogus non-null pointer
        guard_check(g);
    }
}

