use xiom.io;
use xiom.time;
use xiom.ffi.dl;

// Reference implementation: Hot-Reload Module Loader (XIOM)
// Systems Arena -- measures execution speed, memory usage, binary size.
//
// Real dynamic module loading through the stdlib `xiom.ffi.dl` module
// (dlopen/dlsym/dlclose): every cycle opens a shared library, resolves the
// exported function, calls it 100 times, then hot-reloads (a fresh dlopen
// replaces the old handle) and unloads it. The workload is identical for
// every language: libc.so.6 / abs, 1000 cycles x 100 calls, deterministic
// arguments.

fn main() {
  let start = time.Instant.now();

  var checksum: Int = 0;
  var i: Int = 0;
  while i < 1000 {
    match dl_open("libc.so.6") {
      Ok(handle) => {
        match dl_sym(handle, "abs") {
          Ok(addr) => {
            var fn_ptr: fn(Int) -> Int;
            unsafe { fn_ptr = addr as fn(Int) -> Int; }
            var j: Int = 0;
            while j < 100 {
              let arg: Int = (i * 31 + j * 17) % 1000 - 500;
              var value: Int = 0;
              unsafe { value = fn_ptr(arg); }
              checksum = checksum + value;
              j = j + 1;
            }
          },
          Err(_e) => {
            io.println("dlsym failed");
            return;
          }
        }
        match dl_open("libc.so.6") {
          Ok(fresh) => {
            match dl_close(handle) {
              Ok(_) => {},
              Err(_e) => {}
            }
            match dl_close(fresh) {
              Ok(_) => {},
              Err(_e) => {}
            }
          },
          Err(_e) => {
            io.println("reload dlopen failed");
            return;
          }
        }
      },
      Err(_e) => {
        io.println("dlopen failed");
        return;
      }
    }
    i = i + 1;
  }

  let elapsed = start.elapsed();
  let ms = elapsed.as_millis();
  io.println("{\"op\":\"hot-reload\",\"cycles\":1000,\"calls\":100000,\"checksum\":" + checksum.to_str() + ",\"time_ms\":" + ms.to_str() + "}");
}

