// t8-safety-probe -- Language Safety Index (XIOM), probe schema 2.0
//
// Honest, empirically-measured probe. No hardcoded scores.
//
// Methodology: each probe runs in an isolated child process (self re-exec via
// system(3)). The child performs the unsafe operation with CANARY (0xDEADBEEF)
// and SENTINEL (0x0BADF00D) words around the object under attack, then writes
// an observation file. The parent observes the child's exit status AND reads
// the observation:
//
//   signal                 -> OS_CRASH       -> score 2  (process terminated)
//   non-zero exit          -> RUNTIME_PANIC  -> score 6  (error detected)
//   exit 0, no observation -> INCONCLUSIVE   -> unscored (exit code alone is
//                                              NEVER evidence of "silent")
//   exit 0 + canary/sentinel changed -> SILENT_FAILURE -> score 0
//   exit 0 + integrity intact        -> SILENT_UB      -> score 0
//   compile-time rejection of the construct -> COMPILE_ERROR -> score 10
//
// Scoring ladder identical across ALL languages (C, C++, Rust, Zig, Go, Ada,
// XIOM, scripting): 10/6/2/0 -- what happened, measured, not assumed.
//
// Build flags: the probe is compiled by the arena harness with
// config.yaml `languages.systems.xiom.compiler_flags` (--release --target
// native). The probe makes NO assumption about extra flags: if an operation
// (e.g. integer overflow) does not trap under the harness flags, the canary
// observation reports the honest outcome (SILENT_UB, no error detected).
//
// Toolchain notes (verified 2026-09, xiom v0.61.1):
//   - casts are confinement-gated (T001/T007): pointer/integer casts live
//     inside `unsafe` blocks; whole-body-unsafe fns declare `requires`.
//   - system(3) via extern "C"; Str->*UInt8 via local cstr().
//   - Vec indexing is bounds-checked at runtime (out-of-bounds -> trap, 6).
//   - stack-overflow recurses through an INDIRECT call (fn pointer) so the
//     optimizer cannot TCO it into a loop.
//   - io.print is codegen-corrupted -> ALL output uses io.println.
//   - MEASURE ONLY ON THE BENCHMARK PLATFORM (Linux/Docker): Windows runtime
//     trap/reporting behavior differs -- run through docker compose.

use xiom.io;
use xiom.io.fs;
use xiom.env;
use xiom.alloc;
use xiom.string;
use xiom.convert;

extern "C" {
  fn system(command: *UInt8) -> Int32;
}

const N_PROBES: Int = 12;
const CANARY: Int = 3735928559;   // 0xDEADBEEF
const SENTINEL: Int = 195948557;  // 0x0BADF00D
const REPLACED: Int = 291;        // 0x123 -- pattern written through a re-used block

fn probe_count() -> Int
  // @spec T8-P1: the probe count has a single source of truth
  ensures: result == N_PROBES
{
  return N_PROBES;
}

fn cstr(s: Str) -> *UInt8
  requires: s.len() > 0
{
  unsafe {
    return s as *UInt8;
  }
}

fn sys_exec(cmd: Str) -> Int {
  let rc: Int32;
  unsafe {
    rc = system(cstr(cmd));
  }
  return rc as Int;
}

// -- Canary helpers -----------------------------------------------------------

fn store_word(base: *mut UInt8, word: Int, value: Int)
  requires: base != null
{
  unsafe {
    var p = base as *mut Int;
    *(p + word) = value;
  }
}

fn load_word(base: *mut UInt8, word: Int) -> Int
  requires: base != null
{
  unsafe {
    var p = base as *Int;
    return *(p + word);
  }
}

fn bool_str(b: Bool) -> Str {
  if b { return "true"; }
  return "false";
}

fn tri_str(v: Int) -> Str {
  if v == 1 { return "true"; }
  if v == 0 { return "false"; }
  return "null";
}

fn reset_obs(path: Str) -> Int {
  let r = fs_write_text(path, "{\"attack_completed\": false}");
  match r {
    Ok(_) => { return 0; },
    Err(_) => { return -1; },
  }
}

fn write_obs(path: Str, probe_id: Int, canary_ok: Bool, sentinel_ok: Bool, canary_after: Int, sentinel_after: Int, observed: Int) -> Int {
  var payload = "{";
  payload = payload + "\"probe\": " + int_to_string(probe_id);
  payload = payload + ", \"attack_completed\": true";
  payload = payload + ", \"canary_intact\": " + bool_str(canary_ok);
  payload = payload + ", \"sentinel_intact\": " + bool_str(sentinel_ok);
  payload = payload + ", \"canary_before\": " + int_to_string(CANARY);
  payload = payload + ", \"canary_after\": " + int_to_string(canary_after);
  payload = payload + ", \"sentinel_before\": " + int_to_string(SENTINEL);
  payload = payload + ", \"sentinel_after\": " + int_to_string(sentinel_after);
  payload = payload + ", \"observed\": " + int_to_string(observed);
  payload = payload + "}";
  let r = fs_write_text(path, payload);
  match r {
    Ok(_) => { return 0; },
    Err(_) => { return -1; },
  }
}

// -- Probe implementations (child side) ---------------------------------------

fn probe_use_after_free(obs: Str) -> Int {
  let a = alloc(24);
  store_word(a, 0, CANARY);
  store_word(a, 1, 123);
  store_word(a, 2, SENTINEL);
  dealloc(a, 24);
  // Likely block re-use: write a distinct pattern through a new allocation.
  let b = alloc(24);
  store_word(b, 0, SENTINEL);
  store_word(b, 1, 456);
  store_word(b, 2, CANARY);
  let observed = load_word(a, 1); // stale pointer read (use-after-free)
  let a0 = load_word(a, 0);
  let a2 = load_word(a, 2);
  var canary_ok: Bool = true;
  if a0 == SENTINEL {
    if a2 == CANARY {
      // The freed block now holds b's data: the stale pointer aliases live memory.
      canary_ok = false;
    }
  }
  write_obs(obs, 0, canary_ok, true, a2, a0, observed);
  return 0;
}

fn probe_double_free(obs: Str) -> Int {
  let a = alloc(16);
  store_word(a, 0, CANARY);
  store_word(a, 1, SENTINEL);
  dealloc(a, 16);
  let b = alloc(16);
  store_word(b, 0, SENTINEL);
  store_word(b, 1, CANARY);
  dealloc(a, 16); // double free -- frees the block now owned by b
  // If the allocator hands the same block out a third time, aliasing proves
  // the free-list was corrupted and no error was reported.
  let c = alloc(16);
  store_word(c, 0, REPLACED);
  let b0 = load_word(b, 0);
  var canary_ok: Bool = true;
  if b0 == REPLACED {
    canary_ok = false;
  }
  write_obs(obs, 1, canary_ok, true, b0, b0, b0);
  return 0;
}

fn probe_buffer_overflow(obs: Str) -> Int {
  let guard = alloc(8);
  store_word(guard, 0, CANARY);
  var buf = Vec[Int].with_capacity(4);
  buf.push(1);
  buf.push(2);
  buf.push(3);
  buf.push(4);
  let len_before = buf.len();
  let sink = buf[100]; // out-of-bounds read (bounds-checked at runtime)
  let len_after = buf.len();
  let g = load_word(guard, 0);
  var canary_ok: Bool = true;
  if g != CANARY { canary_ok = false; }
  var sentinel_ok: Bool = true;
  if len_after != len_before { sentinel_ok = false; }
  write_obs(obs, 2, canary_ok, sentinel_ok, g, len_after, sink);
  return 0;
}

fn probe_null_deref(obs: Str) -> Int {
  let guard = alloc(8);
  store_word(guard, 0, CANARY);
  var p: *Int;
  unsafe { p = 0 as *Int; }
  var x: Int = 0;
  unsafe { x = *p; } // null dereference
  let g = load_word(guard, 0);
  var canary_ok: Bool = true;
  if g != CANARY { canary_ok = false; }
  write_obs(obs, 3, canary_ok, true, g, g, x);
  return 0;
}

fn probe_integer_overflow(obs: Str) -> Int {
  let guard = alloc(8);
  store_word(guard, 0, CANARY);
  var a: Int = 9223372036854775807;
  var b: Int = a + a; // signed overflow -- trap or wrap depends on harness flags; measured, not assumed
  let g = load_word(guard, 0);
  var canary_ok: Bool = true;
  if g != CANARY { canary_ok = false; }
  write_obs(obs, 4, canary_ok, true, g, g, b);
  return 0;
}

fn probe_use_of_uninit(obs: Str) -> Int {
  let p = alloc(24);
  store_word(p, 1, CANARY);
  store_word(p, 2, SENTINEL);
  let x = load_word(p, 0); // uninitialized word
  let p1 = load_word(p, 1);
  let p2 = load_word(p, 2);
  var canary_ok: Bool = true;
  if p1 != CANARY { canary_ok = false; }
  var sentinel_ok: Bool = true;
  if p2 != SENTINEL { sentinel_ok = false; }
  write_obs(obs, 5, canary_ok, sentinel_ok, p1, p2, x);
  return 0;
}

fn probe_type_confusion(obs: Str) -> Int {
  let base = alloc(16);
  store_word(base, 0, CANARY);
  store_word(base, 1, SENTINEL);
  unsafe {
    var pf = base as *mut Float64;
    *(pf + 1) = 2.71; // float write over the Int sentinel word
  }
  let confused = load_word(base, 0);  // canary word read as Int
  let corrupted = load_word(base, 1); // float bits where the sentinel was
  var canary_ok: Bool = true;
  if confused != CANARY { canary_ok = false; }
  var sentinel_ok: Bool = true;
  if corrupted != SENTINEL { sentinel_ok = false; }
  write_obs(obs, 6, canary_ok, sentinel_ok, confused, corrupted, corrupted);
  return 0;
}

fn probe_stack_overflow(obs: Str) -> Int {
  // Record that the probe started, then recurse until the stack is exhausted.
  write_obs(obs, 7, true, true, CANARY, SENTINEL, 0);
  return recurse(1);
}

// -- B10 expansion: 4 additional canary-checked probes -------------------------

fn probe_buffer_overflow_write(obs: Str) -> Int {
  let guard = alloc(8);
  store_word(guard, 0, CANARY);
  var buf = Vec[Int].with_capacity(4);
  buf.push(1);
  buf.push(2);
  buf.push(3);
  buf.push(4);
  let len_before = buf.len();
  buf[100] = 42; // out-of-bounds write (bounds-checked at runtime)
  let len_after = buf.len();
  let g = load_word(guard, 0);
  var canary_ok: Bool = true;
  if g != CANARY { canary_ok = false; }
  var sentinel_ok: Bool = true;
  if len_after != len_before { sentinel_ok = false; }
  write_obs(obs, 8, canary_ok, sentinel_ok, g, len_after, 42);
  return 0;
}

fn probe_invalid_free(obs: Str) -> Int {
  let a = alloc(24);
  store_word(a, 0, CANARY);
  store_word(a, 1, 111);
  store_word(a, 2, SENTINEL);
  // Free through an INTERIOR pointer (not the allocation base): the allocator
  // either rejects it (traps) or corrupts its free lists silently.
  dealloc(a + 8, 16);
  // If a later allocation hands out the same block, the object was aliased.
  let c = alloc(24);
  store_word(c, 1, REPLACED);
  let a1 = load_word(a, 1);
  var canary_ok: Bool = true;
  if a1 == REPLACED { canary_ok = false; }
  write_obs(obs, 9, canary_ok, true, a1, a1, a1);
  return 0;
}

fn probe_division_by_zero(obs: Str) -> Int {
  let guard = alloc(8);
  store_word(guard, 0, CANARY);
  var a: Int = 1;
  var b: Int = 0;
  var c: Int = 0;
  c = a / b; // division by zero (trap or defined result depends on runtime)
  let g = load_word(guard, 0);
  var canary_ok: Bool = true;
  if g != CANARY { canary_ok = false; }
  write_obs(obs, 10, canary_ok, true, g, g, c);
  return 0;
}

fn probe_invalid_pointer(obs: Str) -> Int {
  let guard = alloc(8);
  store_word(guard, 0, CANARY);
  var p: *Int;
  unsafe { p = 1 as *Int; } // bogus non-null address
  var x: Int = 0;
  unsafe { x = *p; } // read through the invalid pointer
  let g = load_word(guard, 0);
  var canary_ok: Bool = true;
  if g != CANARY { canary_ok = false; }
  write_obs(obs, 11, canary_ok, true, g, g, x);
  return 0;
}

fn recurse(d: Int) -> Int {
  var x: Int = d * 2;
  var next: fn(Int) -> Int = recurse;
  if x > 0 {
    // Indirect call: cannot be tail-call-eliminated, so the stack genuinely grows.
    return next(x);
  }
  return d;
}

fn run_probe(probe_id: Int, obs: Str) -> Int {
  if probe_id == 0 { return probe_use_after_free(obs); }
  if probe_id == 1 { return probe_double_free(obs); }
  if probe_id == 2 { return probe_buffer_overflow(obs); }
  if probe_id == 3 { return probe_null_deref(obs); }
  if probe_id == 4 { return probe_integer_overflow(obs); }
  if probe_id == 5 { return probe_use_of_uninit(obs); }
  if probe_id == 6 { return probe_type_confusion(obs); }
  if probe_id == 7 { return probe_stack_overflow(obs); }
  if probe_id == 8 { return probe_buffer_overflow_write(obs); }
  if probe_id == 9 { return probe_invalid_free(obs); }
  if probe_id == 10 { return probe_division_by_zero(obs); }
  if probe_id == 11 { return probe_invalid_pointer(obs); }
  return 0;
}

// -- Parent: isolate each probe, read exit status + observation ---------------

fn obs_flag(path: Str, key: Str) -> Int {
  let r = fs_read_text(path);
  match r {
    Ok(text) => {
      if str_contains(text, "\"" + key + "\": true") { return 1; }
      if str_contains(text, "\"" + key + "\": false") { return 0; }
      return -1;
    },
    Err(_) => { return -1; },
  }
}

fn measure(probe_id: Int, self_path: Str, obs_path: Str) -> Int {
  // Start from a clean observation: a stale file must never be read as evidence.
  let reset = reset_obs(obs_path);
  if reset != 0 { return -1; }
  var cmd = self_path + " --probe " + int_to_string(probe_id) + " " + obs_path;
  var rc = sys_exec(cmd);
  if rc < 0 { return -1; } // spawn failure -> inconclusive, never "silent"
  let sig = rc & 127;
  let code = (rc >> 8) & 255;
  if sig == 127 { return -1; } // shell could not run the command
  if sig != 0 {
    return 2; // killed by signal -> os_crash (process terminated)
  }
  if code != 0 {
    return 6; // non-zero exit -> runtime_panic
  }
  // Survived: only the observation can justify a "silent" outcome.
  if obs_flag(obs_path, "attack_completed") != 1 { return -1; }
  if obs_flag(obs_path, "canary_intact") == 0 { return 0; }
  if obs_flag(obs_path, "sentinel_intact") == 0 { return 0; }
  return 0;
}

fn outcome_of(score: Int, obs_path: Str) -> Str {
  if score == 2 { return "OS_CRASH"; }
  if score == 6 { return "RUNTIME_PANIC"; }
  if score == -1 { return "INCONCLUSIVE"; }
  if obs_flag(obs_path, "canary_intact") == 0 { return "SILENT_FAILURE"; }
  if obs_flag(obs_path, "sentinel_intact") == 0 { return "SILENT_FAILURE"; }
  return "SILENT_UB";
}

fn mechanism_of(outcome: Str) -> Str {
  if outcome == "OS_CRASH" { return "os_crash"; }
  if outcome == "RUNTIME_PANIC" { return "runtime_panic"; }
  if outcome == "INCONCLUSIVE" { return "inconclusive"; }
  return "silent";
}

fn error_detected_of(outcome: Str) -> Bool {
  if outcome == "OS_CRASH" { return true; }
  if outcome == "RUNTIME_PANIC" { return true; }
  return false;
}

fn survived_of(outcome: Str) -> Bool {
  if outcome == "OS_CRASH" { return false; }
  if outcome == "RUNTIME_PANIC" { return false; }
  return true;
}

fn state_tri(score: Int, obs_path: Str) -> Int {
  if score == 2 { return -1; }
  if score == 6 { return -1; }
  if score == -1 { return -1; }
  let canary = obs_flag(obs_path, "canary_intact");
  if canary == 0 { return 1; }
  let sentinel = obs_flag(obs_path, "sentinel_intact");
  if sentinel == 0 { return 1; }
  if canary == 1 { if sentinel == 1 { return 0; } }
  return -1;
}

fn probe_name(id: Int) -> Str {
  if id == 0 { return "use-after-free"; }
  if id == 1 { return "double-free"; }
  if id == 2 { return "buffer-overflow"; }
  if id == 3 { return "null-deref"; }
  if id == 4 { return "integer-overflow"; }
  if id == 5 { return "use-of-uninit"; }
  if id == 6 { return "type-confusion"; }
  if id == 7 { return "stack-overflow"; }
  if id == 8 { return "buffer-overflow-write"; }
  if id == 9 { return "invalid-free"; }
  if id == 10 { return "division-by-zero"; }
  return "invalid-pointer";
}

// FAIRNESS-V1 B9: safety track per probe (shared taxonomy with the harness;
// contract scoring.safety_tracks). Report is per-probe metadata, not a score.
fn probe_track(id: Int) -> Str {
  if id == 0 { return "SAFE_SUBSET"; }        // use-after-free
  if id == 1 { return "SAFE_SUBSET"; }        // double-free
  if id == 2 { return "SAFE_SUBSET"; }        // buffer-overflow
  if id == 3 { return "FAULT_CONTAINMENT"; }  // null-deref
  if id == 4 { return "UNSAFE_BOUNDARY"; }    // integer-overflow
  if id == 5 { return "SAFE_SUBSET"; }        // use-of-uninit
  if id == 6 { return "UNSAFE_BOUNDARY"; }    // type-confusion
  if id == 7 { return "FAULT_CONTAINMENT"; }  // stack-overflow
  if id == 8 { return "SAFE_SUBSET"; }        // buffer-overflow-write
  if id == 9 { return "UNSAFE_BOUNDARY"; }    // invalid-free
  if id == 10 { return "FAULT_CONTAINMENT"; } // division-by-zero
  return "UNSAFE_BOUNDARY";                   // invalid-pointer
}

fn main() -> Int {
  var args = env.args();

  // Child mode -- nested ifs: args[1]/args[2] are read only after an explicit
  // len() guard (independent of `and` short-circuit semantics). The
  // observation path (args[3]) is OPTIONAL so the harness startup sanity check
  // (`<binary> --probe 999`, three args) stays lightweight.
  if args.len() >= 3 {
    if args[1] == "--probe" {
