const std = @import("std");

const POOL_SIZE = 1024 * 1024;
const MIN_BLOCK = 64;
const MAX_ORDER = 14;

const Block = struct {
    free: bool,
    order: usize,
    next: ?*Block,
};

var pool: [POOL_SIZE]u8 align(64) = [_]u8{0} ** POOL_SIZE;
var free_lists: [MAX_ORDER + 1]?*Block = [_]?*Block{null} ** (MAX_ORDER + 1);
var initialized: bool = false;

fn orderForSize(size: usize) usize {
    var block_size: usize = MIN_BLOCK;
    var order: usize = 0;
    while (block_size < size + @sizeOf(Block)) : (order += 1) {
        block_size <<= 1;
    }
    return if (order > MAX_ORDER) MAX_ORDER else order;
}

fn blockSizeForOrder(order: usize) usize {
    return @as(usize, MIN_BLOCK) << @intCast(order);
}

fn splitBlock(order: usize) ?*Block {
    if (order > MAX_ORDER) return null;
    if (free_lists[order]) |block| {
        free_lists[order] = block.next;
        block.free = false;
        return block;
    }
    if (order == MAX_ORDER) return null;
    const bigger = splitBlock(order + 1) orelse return null;
    const half = blockSizeForOrder(order);
    const buddy: *Block = @ptrFromInt(@intFromPtr(bigger) + half);
    buddy.free = true;
    buddy.order = order;
    buddy.next = free_lists[order];
    free_lists[order] = buddy;
    bigger.free = false;
    bigger.order = order;
    return bigger;
}

fn buddyInit() void {
    if (initialized) return;
    @memset(&pool, 0);
    @memset(&free_lists, null);
    const root: *Block = @alignCast(@ptrCast(&pool));
    root.free = true;
    root.order = MAX_ORDER;
    root.next = null;
    free_lists[MAX_ORDER] = root;
    initialized = true;
}

fn buddyAlloc(size: usize) ?*anyopaque {
    if (!initialized) buddyInit();
    if (size == 0) return null;
    const order = orderForSize(size);
    const block = splitBlock(order) orelse return null;
    return @ptrFromInt(@intFromPtr(block) + @sizeOf(Block));
}

fn buddyFree(ptr: ?*anyopaque) void {
    if (ptr == null) return;
    var block: *Block = @ptrFromInt(@intFromPtr(ptr) - @sizeOf(Block));
    block.free = true;
    while (block.order < MAX_ORDER) {
        const bsize = blockSizeForOrder(block.order);
        const addr: usize = @intFromPtr(block) - @intFromPtr(&pool[0]);
        const buddy_addr = addr ^ bsize;
        if (buddy_addr + bsize > POOL_SIZE) break;
        const buddy: *Block = @ptrFromInt(@intFromPtr(&pool[0]) + buddy_addr);
        if (!buddy.free or buddy.order != block.order) break;
        var prev: *?*Block = &free_lists[block.order];
        while (prev.*) |p| : (prev = &p.next) {
            if (p == buddy) break;
        }
        if (prev.* != null) {
            prev.* = buddy.next;
        }
        if (addr > buddy_addr) {
            block = buddy;
        }
        block.order += 1;
    }
    block.next = free_lists[block.order];
    free_lists[block.order] = block;
}

pub fn main() void {
    buddyInit();
    const N = 10000;
    var ptrs: [N]?*anyopaque = undefined;

    var i: usize = 0;
    while (i < N) : (i += 1) {
        const sz: usize = 64 + (i * 997) % 4096;
        ptrs[i] = buddyAlloc(sz);
    }

    i = 0;
    while (i < N) : (i += 2) {
        buddyFree(ptrs[i]);
    }

    i = 0;
    while (i < N) : (i += 2) {
        const sz: usize = 128 + (i * 503) % 2048;
        ptrs[i] = buddyAlloc(sz);
    }

    i = 0;
    while (i < N) : (i += 1) {
        buddyFree(ptrs[i]);
    }

    std.debug.print("OK\n", .{});
}

