const std = @import("std");

const ORDER: usize = 4;
const MAX_KEYS: usize = ORDER - 1;
const MAX_CHILDREN: usize = ORDER;
const NODE_POOL_SIZE: usize = 10000;

const BTreeEntry = struct {
    key: i64,
    value: i64,
    child_offset: i64,
};

const BTreeNode = struct {
    num_keys: usize,
    is_leaf: bool,
    parent_offset: i64,
    entries: [MAX_KEYS]BTreeEntry,
    children: [MAX_CHILDREN]i64,
};

var node_pool: [NODE_POOL_SIZE]BTreeNode = undefined;
var pool_idx: usize = 0;

fn allocNode() ?*BTreeNode {
    if (pool_idx >= NODE_POOL_SIZE) return null;
    var node = &node_pool[pool_idx];
    node.* = std.mem.zeroes(BTreeNode);
    node.is_leaf = true;
    pool_idx += 1;
    return node;
}

fn btreeSearch(node: *const BTreeNode, key: i64) ?i64 {
    var i: usize = 0;
    while (i < node.num_keys and key > node.entries[i].key) : (i += 1) {}
    if (i < node.num_keys and key == node.entries[i].key) {
        return node.entries[i].value;
    }
    return null;
}

fn btreeInsertNonfull(node: *BTreeNode, key: i64, value: i64) void {
    if (node.num_keys >= MAX_KEYS) return;
    var i: usize = node.num_keys;
    while (i > 0 and key < node.entries[i - 1].key) : (i -= 1) {
        node.entries[i] = node.entries[i - 1];
    }
    node.entries[i].key = key;
    node.entries[i].value = value;
    node.entries[i].child_offset = -1;
    node.num_keys += 1;
}

pub fn main() !void {
    // NOTE: @memset instead of std.mem.zeroes -- zeroes on a large array
    // hangs the Zig 0.13 optimizer in ReleaseFast mode (verified locally).
    @memset(std.mem.asBytes(&node_pool), 0);
    pool_idx = 0;

    const root = allocNode() orelse return error.OutOfMemory;

    var i: i64 = 0;
    while (i < 50000) : (i += 1) {
        btreeInsertNonfull(root, i * 3, i * 7);
    }

    var found: usize = 0;
    i = 0;
    while (i < 20000) : (i += 1) {
        if (btreeSearch(root, i * 5)) |_| {
            found += 1;
        }
    }

    std.debug.print("OK\n", .{});
}

