// t8-safety-probe -- Language Safety Index (Zig), schema 2.0 observed evidence
//
// P1.1 (hardening plan): 12 probes, each fork-isolated, with canary/sentinel
// guards read and written through volatile pointers so -O cannot elide the
// evidence; the probe child carries the observation to the parent over a pipe
// and the parent classifies from it. Zig 0.13 has no block comments, so this
// file uses line comments only.
//
// Ladder (contract scoring.safety_ladder): compile_error 10, runtime_panic 6,
// os_crash 2, silent 0; INCONCLUSIVE is unscored (null), never "silent".
//
// Compiled with ReleaseFast (arena default): runtime safety checks are off,
// which is what the arena measures. Debug/ReleaseSafe would panic on several
// probes and score runtime_panic instead.

const std = @import("std");
const linux = std.os.linux;

const CANARY: u32 = 0xDEADBEEF;
const SENTINEL: u64 = 0x0BADF00D;
const N_PROBES: usize = 12;

// Observation carried from the child to the parent over a pipe. The struct
// crosses one process boundary only (same ABI), so its exact layout is free;
// extern keeps it C-shaped and padding-stable.
const Obs = extern struct {
    attack_completed: i32,
    canary_before: u32,
    canary_after: u32,
    sentinel_before: u64,
    sentinel_after: u64,
};

// A guarded allocation: the dangerous operation must cross canary/sentinel.
// The guards are observed through volatile pointers -- a plain read gets
// optimised away at ReleaseFast and the observed evidence would be a lie.
const Guarded = extern struct {
    buf: [16]u8,
    canary: u32,
    sentinel: u64,
};

// libc allocation, exactly like the C fixture: the probes must observe the
// same allocator behavior (double-free/invalid-free abort in glibc) that the
// other systems languages are measured against. The Zig Allocator wrapper is
// deliberately not used: Allocator.free() poisons the payload before freeing,
// which would corrupt the canary observation and misreport the probe.
extern "c" fn malloc(size: usize) ?*anyopaque;
extern "c" fn free(ptr: ?*anyopaque) void;

// Observation slot set in the probe child before the probe runs.
var g_obs: ?*Obs = null;

fn allocGuarded() ?*Guarded {
    const raw = malloc(@sizeOf(Guarded)) orelse return null;
    return @as(*Guarded, @alignCast(@ptrCast(raw)));
}

fn freeGuarded(g: *Guarded) void {
    free(g);
}

fn guardSet(g: *Guarded) void {
    var i: usize = 0;
    while (i < 16) : (i += 1) {
        @as(*volatile u8, @ptrCast(&g.buf[i])).* = 0x41;
    }
    @as(*volatile u32, @ptrCast(&g.canary)).* = CANARY;
    @as(*volatile u64, @ptrCast(&g.sentinel)).* = SENTINEL;
    if (g_obs) |obs| {
        obs.canary_before = @as(*volatile u32, @ptrCast(&g.canary)).*;
        obs.sentinel_before = @as(*volatile u64, @ptrCast(&g.sentinel)).*;
    }
}

fn guardCheck(g: *Guarded) void {
    if (g_obs) |obs| {
        obs.canary_after = @as(*volatile u32, @ptrCast(&g.canary)).*;
        obs.sentinel_after = @as(*volatile u64, @ptrCast(&g.sentinel)).*;
    }
}

// -- Probe implementations (every dangerous operation is intentional) --------

fn probeUseAfterFree() void {
    const g = allocGuarded() orelse return;
    guardSet(g);
    freeGuarded(g);
    const x = @as(*volatile u8, @ptrCast(&g.buf[0])).*; // USE AFTER FREE (read)
    _ = x;
    guardCheck(g);
}

fn probeDoubleFree() void {
    const g = allocGuarded() orelse return;
    guardSet(g);
    freeGuarded(g);
    freeGuarded(g); // DOUBLE FREE
    guardCheck(g);
}

fn probeBufferOverflow() void {
    const g = allocGuarded() orelse return;
    guardSet(g);
    const base: [*]u8 = @ptrCast(&g.buf);
    const x = @as(*volatile u8, @ptrCast(base + 200)).*; // OUT-OF-BOUNDS READ
    _ = x;
    guardCheck(g);
}

fn probeNullDeref() void {
    const p: *allowzero volatile i32 = @ptrFromInt(0);
    const x = p.*; // NULL DEREFERENCE
    _ = x;
}

fn probeIntegerOverflow() void {
    var g: Guarded = std.mem.zeroes(Guarded);
    guardSet(&g);
    var a: i32 = std.math.maxInt(i32);
    const ap: *volatile i32 = &a;
    ap.* = ap.* + 1; // SIGNED OVERFLOW -- UB at ReleaseFast (checks are off)
    guardCheck(&g);
}

fn probeUseOfUninit() void {
    var g: Guarded = std.mem.zeroes(Guarded);
    guardSet(&g);
    var x: i32 = undefined; // UNINITIALIZED
    const xp: *volatile i32 = &x;
    const y = xp.*;
    _ = y;
    guardCheck(&g);
}

fn probeTypeConfusion() void {
    var g: Guarded = std.mem.zeroes(Guarded);
    guardSet(&g);
    var f: f32 = 3.14;
    const ip: *volatile i32 = @ptrCast(&f);
    const confused = ip.*;
    _ = confused;
    guardCheck(&g);
}

fn probeStackOverflow() void {
    var dummy: [4096]u8 = [_]u8{0} ** 4096;
    dummy[0] = 1;
    if (dummy[0] == 1) @call(.never_inline, probeStackOverflow, .{});
    std.mem.doNotOptimizeAway(dummy[0]); // anti-TCO
}

fn probeBufferOverflowWrite() void {
    const g = allocGuarded() orelse return;
    guardSet(g);
    const base: [*]u8 = @ptrCast(&g.buf);
    var i: usize = 0;
    while (i < 256) : (i += 1) {
        @as(*volatile u8, @ptrCast(base + i)).* = @truncate(i); // OOB WRITE over canary/sentinel
    }
    const sink = @as(*volatile u8, @ptrCast(&g.buf[0])).*;
    _ = sink;
    guardCheck(g);
}

fn probeInvalidFree() void {
    var g: Guarded = std.mem.zeroes(Guarded);
    guardSet(&g);
    free(&g); // INVALID FREE of a stack address
    guardCheck(&g);
}

fn probeDivisionByZero() void {
    var g: Guarded = std.mem.zeroes(Guarded);
    guardSet(&g);
    var z: i32 = 0;
    const zp: *volatile i32 = &z;
    var q: i32 = 0;
    const qp: *volatile i32 = &q;
    // The volatile store forces the division to execute; a plain local gets
    // deleted together with the UB operation (observed while validating).
    qp.* = @divTrunc(@as(i32, 1), zp.*); // DIVISION BY ZERO -- ReleaseFast: SIGFPE
    guardCheck(&g);
}

fn probeInvalidPointer() void {
    var g: Guarded = std.mem.zeroes(Guarded);
    guardSet(&g);
    const p: *align(1) volatile i32 = @ptrFromInt(0xdeadbeef); // bogus non-null pointer
    p.* = 1;
    guardCheck(&g);
}

// -- Probe metadata ----------------------------------------------------------

const probe_names = [N_PROBES][]const u8{
    "use-after-free",   "double-free",    "buffer-overflow",  "null-deref",
    "integer-overflow", "use-of-uninit",  "type-confusion",   "stack-overflow",
    "buffer-overflow-write", "invalid-free", "division-by-zero", "invalid-pointer",
};
const probe_tracks = [N_PROBES][]const u8{
    "SAFE_SUBSET",       "SAFE_SUBSET",   "SAFE_SUBSET",       "FAULT_CONTAINMENT",
    "UNSAFE_BOUNDARY",   "SAFE_SUBSET",   "UNSAFE_BOUNDARY",   "FAULT_CONTAINMENT",
    "SAFE_SUBSET",       "UNSAFE_BOUNDARY", "FAULT_CONTAINMENT", "UNSAFE_BOUNDARY",
};
const probe_fns = [N_PROBES]*const fn () void{
    probeUseAfterFree,        probeDoubleFree,       probeBufferOverflow,     probeNullDeref,
    probeIntegerOverflow,     probeUseOfUninit,      probeTypeConfusion,      probeStackOverflow,
    probeBufferOverflowWrite, probeInvalidFree,      probeDivisionByZero,     probeInvalidPointer,
};

// -- Isolation + classification ----------------------------------------------

const RunResult = struct {
    rc: i32,
    obs: ?Obs,
};

fn runIsolated(fn_ptr: *const fn () void) RunResult {
    var fds: [2]i32 = undefined;
    if (std.posix.errno(linux.pipe2(&fds, .{})) != .SUCCESS) return .{ .rc = -1001, .obs = null };
    const pid = linux.fork();
    if (pid == 0) {
        _ = linux.close(fds[0]);
        var obs = std.mem.zeroes(Obs);
        g_obs = &obs;
        fn_ptr();
        obs.attack_completed = 1;
        const bytes: [*]const u8 = @ptrCast(&obs);
        _ = linux.write(fds[1], bytes, @sizeOf(Obs));
        _ = linux.close(fds[1]);
        std.process.exit(0);
    }
    _ = linux.close(fds[1]);
    var out = std.mem.zeroes(Obs);
    const n = linux.read(fds[0], @ptrCast(&out), @sizeOf(Obs));
    _ = linux.close(fds[0]);
    var status: u32 = 0;
    _ = linux.waitpid(@intCast(pid), &status, 0);
    if (linux.W.IFSIGNALED(status)) {
        return .{ .rc = @intCast(linux.W.TERMSIG(status)), .obs = null }; // os crash
    }
    if (linux.W.IFEXITED(status) and linux.W.EXITSTATUS(status) != 0) {
        return .{ .rc = -@as(i32, @intCast(linux.W.EXITSTATUS(status))), .obs = null }; // runtime exit
    }
    if (n != @sizeOf(Obs)) return .{ .rc = -1000, .obs = null }; // exit 0 without observation
    return .{ .rc = 0, .obs = out };
}

const Classified = struct {
    outcome: []const u8 = "INCONCLUSIVE",
    mech_buf: [64]u8 = undefined,
    mech_len: usize = 0,
    error_detected: i32 = -1,
    survived: i32 = -1,
    corrupted: i32 = -1,
    canary_intact: i32 = -1,
    sentinel_intact: i32 = -1,
    has_obs: bool = false,
    score: i32 = -1,
    obs: Obs = std.mem.zeroes(Obs),

    fn mechanism(c: *const Classified) []const u8 {
        return c.mech_buf[0..c.mech_len];
    }
};

fn setMech(c: *Classified, comptime fmt: []const u8, args: anytype) void {
    const s = std.fmt.bufPrint(&c.mech_buf, fmt, args) catch {
        c.mech_len = 0;
        return;
    };
    c.mech_len = s.len;
}

fn classify(rc: i32, obs: ?Obs) Classified {
    var c = Classified{};
    if (rc > 0) {
        c.outcome = "OS_CRASH";
        setMech(&c, "os_crash(signal {d})", .{rc});
        c.error_detected = 1;
        c.survived = 0;
        c.corrupted = 0;
        c.score = 2;
        return c;
    }
    if (rc < 0 and rc != -1000) {
        c.outcome = "RUNTIME_PANIC";
        setMech(&c, "runtime_panic(exit {d})", .{-rc});
        c.error_detected = 1;
        c.survived = 0;
        c.corrupted = 0;
        c.score = 6;
        return c;
    }
    const o = obs orelse {
        setMech(&c, "exit 0 without observation (unscored)", .{});
        return c;
    };
    c.has_obs = true;
    c.obs = o;
    const canary_mutated = o.canary_before != o.canary_after;
    const sentinel_mutated = o.sentinel_before != o.sentinel_after;
    c.canary_intact = if (canary_mutated) 0 else 1;
    c.sentinel_intact = if (sentinel_mutated) 0 else 1;
    c.error_detected = 0;
    c.survived = 1;
    if (o.attack_completed != 1) {
        setMech(&c, "attack did not complete (unscored)", .{});
        return c;
    }
    const corrupted = canary_mutated or sentinel_mutated;
    c.corrupted = if (corrupted) 1 else 0;
    if (corrupted) {
        c.outcome = "SILENT_FAILURE";
        setMech(&c, "silent(state corruption confirmed by canary/sentinel)", .{});
        c.score = 0;
    } else {
        c.outcome = "SILENT_UB";
        setMech(&c, "silent(unreported UB; no corruption observed)", .{});
        c.score = 0;
    }
    return c;
}

fn tb(v: i32) []const u8 {
    return if (v < 0) "null" else if (v > 0) "true" else "false";
}

fn writeNumOrNull(w: anytype, v: anytype) !void {
    if (v == 0) try w.writeAll("null") else try w.print("{d}", .{v});
}

pub fn main() !void {
    // Build the whole report in memory and print it once, after every fork has
    // completed: stdout stays untouched across fork(), so no child can inherit
    // a partial buffer and corrupt the JSON.
    var out = std.ArrayList(u8).init(std.heap.page_allocator);
    defer out.deinit();
    const w = out.writer();
    try w.writeAll("{\"test\":\"t8-safety-probe\",\"language\":\"Zig\",\"schema_version\":\"2.0\",");
    try w.writeAll("\"note\":\"Each probe isolated in a forked child; canary/sentinel observations carried over a pipe; parent classifies from evidence.\",\"probes\":[");
    var total: i64 = 0;
    var scored: i32 = 0;
    var i: usize = 0;
    while (i < N_PROBES) : (i += 1) {
        const r = runIsolated(probe_fns[i]);
        const c = classify(r.rc, r.obs);
        if (c.score >= 0) {
            total += c.score;
            scored += 1;
        }
        if (i > 0) try w.writeAll(",");
        try w.print("{{\"name\":\"{s}\",\"track\":\"{s}\",\"outcome_class\":\"{s}\",\"mechanism\":\"{s}\",\"error_detected\":{s},\"program_survived\":{s},\"state_corrupted\":{s},\"canary_intact\":{s},\"sentinel_intact\":{s},\"canary_before\":", .{
            probe_names[i], probe_tracks[i], c.outcome, c.mechanism(),
            tb(c.error_detected), tb(c.survived), tb(c.corrupted),
            tb(c.canary_intact), tb(c.sentinel_intact),
        });
        try writeNumOrNull(w, if (c.has_obs) c.obs.canary_before else 0);
        try w.writeAll(",\"canary_after\":");
        try writeNumOrNull(w, if (c.has_obs) c.obs.canary_after else 0);
        try w.writeAll(",\"sentinel_before\":");
        try writeNumOrNull(w, if (c.has_obs) c.obs.sentinel_before else 0);
        try w.writeAll(",\"sentinel_after\":");
        try writeNumOrNull(w, if (c.has_obs) c.obs.sentinel_after else 0);
        try w.print(",\"attack_completed\":{s},\"containment\":false,\"containment_note\":\"parent-observed execution\",\"score\":", .{
            if (c.has_obs) tb(c.obs.attack_completed) else "true",
        });
        if (c.score < 0) try w.writeAll("null}") else try w.print("{d}}}", .{c.score});
    }
    const index: i32 = if (scored > 0) @intCast(@divTrunc(total * 100, @as(i64, scored) * 10)) else 0;
    try w.print("],\"safety_index\":{d}}}\n", .{index});
    try std.io.getStdOut().writeAll(out.items);
}

