// t8-safety-probe -- Language Safety Index (Go), schema 2.0 observed evidence
//
// P1.1 (hardening plan): 12 probes, each isolated in a re-executed child
// (fork() is not usable from the Go runtime), with canary/sentinel guards
// observed through sync/atomic so the evidence cannot be elided; the child
// writes its observation to stdout and the parent classifies from it.
//
// Probe policy -- the least-permissive path that still compiles:
//   * Go expresses directly: slice bounds (runtime panic), nil dereference
//     (panic), integer division by zero (panic), stack exhaustion (fatal),
//     integer wrap and zero-value reads (silent, language-defined), type puns
//     through unsafe (silent), bogus pointers through unsafe (runtime fatal).
//   * Go has no manual free, so double-free and invalid-free are attempted
//     through cgo (the documented Go FFI boundary, as in the t3 loader):
//     C.malloc/C.free reach the same glibc allocator as the C/C++/Zig
//     fixtures, and the mechanism says so.
//   * use-after-free is a pure-Go stale pointer: drop the reference, force
//     the GC, then read through the saved address.
//
// Ladder (contract scoring.safety_ladder): compile_error 10, runtime_panic 6,
// os_crash 2, silent 0; INCONCLUSIVE is unscored (null), never "silent".

package main

/*
#include <stdlib.h>
*/
import "C"

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"math"
	"os"
	"os/exec"
	"runtime"
	"sync/atomic"
	"syscall"
	"unsafe"
)

const (
	canary   uint32 = 0xDEADBEEF
	sentinel uint64 = 0x0BADF00D
)

// Obs carries the child's observation to the parent (stdout, JSON line).
type Obs struct {
	AttackCompleted int    `json:"attack_completed"`
	CanaryBefore    uint32 `json:"canary_before"`
	CanaryAfter     uint32 `json:"canary_after"`
	SentinelBefore  uint64 `json:"sentinel_before"`
	SentinelAfter   uint64 `json:"sentinel_after"`
}

// Guarded is the protected allocation: the dangerous operation must cross
// canary/sentinel. The guard fields are accessed through sync/atomic, the Go
// equivalent of volatile -- an atomic access cannot be optimised away.
type Guarded struct {
	buf      [16]byte
	canary   uint32
	sentinel uint64
}

var gObs *Obs

// sink globals make "defined but observable" operations non-elidable.
var sink32 int32
var sinkU32 uint32

func guardSet(g *Guarded) {
	for i := 0; i < 16; i++ {
		g.buf[i] = 0x41
	}
	atomic.StoreUint32(&g.canary, canary)
	atomic.StoreUint64(&g.sentinel, sentinel)
	if gObs != nil {
		gObs.CanaryBefore = atomic.LoadUint32(&g.canary)
		gObs.SentinelBefore = atomic.LoadUint64(&g.sentinel)
	}
}

func guardCheck(g *Guarded) {
	if gObs != nil {
		gObs.CanaryAfter = atomic.LoadUint32(&g.canary)
		gObs.SentinelAfter = atomic.LoadUint64(&g.sentinel)
	}
}

// -- Probe implementations ---------------------------------------------------

func probeUseAfterFree() {
	g := &Guarded{}
	guardSet(g)
	addr := uintptr(unsafe.Pointer(g))
	g = nil
	runtime.GC()
	runtime.GC()
	// USE AFTER FREE: read through the stale address after the GC ran.
	_ = *(*byte)(unsafe.Pointer(addr))
	guardCheck((*Guarded)(unsafe.Pointer(addr)))
}

func probeDoubleFree() {
	g := (*Guarded)(C.malloc(C.size_t(unsafe.Sizeof(Guarded{}))))
	if g == nil {
		return
	}
	guardSet(g)
	C.free(unsafe.Pointer(g))
	C.free(unsafe.Pointer(g)) // DOUBLE FREE (cgo, glibc)
	guardCheck(g)
}

func probeBufferOverflow() {
	g := &Guarded{}
	guardSet(g)
	idx := 200
	_ = g.buf[idx] // OUT-OF-BOUNDS READ (variable index -> runtime bounds check)
	guardCheck(g)
}

func probeNullDeref() {
	var p *int32
	_ = *p // NULL DEREFERENCE -> panic
}

func probeIntegerOverflow() {
	g := &Guarded{}
	guardSet(g)
	a := int32(math.MaxInt32)
	b := a + 1 // silent wrap (defined in Go; not detected)
	atomic.StoreInt32(&sink32, b)
	guardCheck(g)
}

func probeUseOfUninit() {
	g := &Guarded{}
	guardSet(g)
	var x int32 // zero value -- Go zero-initialises
	atomic.StoreInt32(&sink32, x)
	guardCheck(g)
}

func probeTypeConfusion() {
	g := &Guarded{}
	guardSet(g)
	f := float32(3.14)
	atomic.StoreInt32(&sink32, *(*int32)(unsafe.Pointer(&f)))
	guardCheck(g)
}

func probeStackOverflow() {
	var dummy [4096]byte
	dummy[0] = 1
	if dummy[0] == 1 {
		probeStackOverflow()
	}
	atomic.StoreUint32(&sinkU32, uint32(dummy[0])) // anti-TCO (Go never TCOs)
}

func probeBufferOverflowWrite() {
	g := &Guarded{}
	guardSet(g)
	buf := g.buf[:]
	for i := 0; i < 256; i++ {
		buf[i] = byte(i) // OUT-OF-BOUNDS WRITE -> panic at the first OOB byte
	}
	atomic.StoreUint32(&sinkU32, uint32(g.buf[0]))
}

func probeInvalidFree() {
	g := &Guarded{}
	guardSet(g)
	C.free(unsafe.Pointer(g)) // INVALID FREE of a Go stack address (cgo, glibc)
	guardCheck(g)
}

func probeDivisionByZero() {
	g := &Guarded{}
	guardSet(g)
	z := int32(0)
	atomic.StoreInt32(&sink32, int32(1)/z) // DIVISION BY ZERO -> panic
	guardCheck(g)
}

func probeInvalidPointer() {
	g := &Guarded{}
	guardSet(g)
	p := (*int32)(unsafe.Pointer(uintptr(0xdeadbeef))) // bogus non-null pointer
	*p = 1
	guardCheck(g)
}

// -- Probe metadata ----------------------------------------------------------

type probeDef struct {
	name  string
	track string
	fn    func()
}

var probeDefs = []probeDef{
	{"use-after-free", "SAFE_SUBSET", probeUseAfterFree},
	{"double-free", "SAFE_SUBSET", probeDoubleFree},
	{"buffer-overflow", "SAFE_SUBSET", probeBufferOverflow},
	{"null-deref", "FAULT_CONTAINMENT", probeNullDeref},
	{"integer-overflow", "UNSAFE_BOUNDARY", probeIntegerOverflow},
	{"use-of-uninit", "SAFE_SUBSET", probeUseOfUninit},
	{"type-confusion", "UNSAFE_BOUNDARY", probeTypeConfusion},
	{"stack-overflow", "FAULT_CONTAINMENT", probeStackOverflow},
	{"buffer-overflow-write", "SAFE_SUBSET", probeBufferOverflowWrite},
	{"invalid-free", "UNSAFE_BOUNDARY", probeInvalidFree},
	{"division-by-zero", "FAULT_CONTAINMENT", probeDivisionByZero},
	{"invalid-pointer", "UNSAFE_BOUNDARY", probeInvalidPointer},
}

// -- Child mode --------------------------------------------------------------

func runProbeChild(name string) {
	for _, d := range probeDefs {
		if d.name == name {
			gObs = &Obs{}
			d.fn()
			gObs.AttackCompleted = 1
			data, _ := json.Marshal(gObs)
			os.Stdout.Write(data)
			os.Stdout.Write([]byte("\n"))
			os.Exit(0)
		}
	}
	os.Exit(0)
}

// -- Isolation + classification (parent) -------------------------------------

type runResult struct {
	rc  int
	obs *Obs
}

func runIsolated(name string) runResult {
	var stdout bytes.Buffer
	cmd := exec.Command(os.Args[0], "-probe", name)
	cmd.Stdout = &stdout
	cmd.Stderr = nil // discard panic traces
	err := cmd.Run()
	if err != nil {
		var exitErr *exec.ExitError
		if errors.As(err, &exitErr) {
			if ws, ok := exitErr.Sys().(syscall.WaitStatus); ok && ws.Signaled() {
				return runResult{rc: int(ws.Signal())} // os crash
			}
			return runResult{rc: -exitErr.ExitCode()} // runtime exit
		}
		return runResult{rc: -1001} // spawn failure
	}
	var obs Obs
	if json.Unmarshal(bytes.TrimSpace(stdout.Bytes()), &obs) != nil {
		return runResult{rc: -1000} // exit 0 without observation
	}
	return runResult{rc: 0, obs: &obs}
}

type classified struct {
	outcome       string
	mechanism     string
	errorDetected int
	survived      int
	corrupted     int
	canaryIntact  int
	sentinelIntact int
	hasObs        bool
	score         int
	obs           Obs
}

func classify(rc int, obs *Obs) classified {
	c := classified{
		outcome: "INCONCLUSIVE", errorDetected: -1, survived: -1,
		corrupted: -1, canaryIntact: -1, sentinelIntact: -1, score: -1,
	}
	if rc > 0 {
		c.outcome = "OS_CRASH"
		c.mechanism = fmt.Sprintf("os_crash(signal %d)", rc)
		c.errorDetected, c.survived, c.corrupted, c.score = 1, 0, 0, 2
		return c
	}
	if rc < 0 && rc != -1000 {
		c.outcome = "RUNTIME_PANIC"
		c.mechanism = fmt.Sprintf("runtime_panic(exit %d)", -rc)
		c.errorDetected, c.survived, c.corrupted, c.score = 1, 0, 0, 6
		return c
	}
	if obs == nil {
		c.mechanism = "exit 0 without observation (unscored)"
		return c
	}
	c.hasObs = true
	c.obs = *obs
	canaryMutated := obs.CanaryBefore != obs.CanaryAfter
	sentinelMutated := obs.SentinelBefore != obs.SentinelAfter
	c.canaryIntact = boolInt(!canaryMutated)
	c.sentinelIntact = boolInt(!sentinelMutated)
	c.errorDetected, c.survived = 0, 1
	if obs.AttackCompleted != 1 {
		c.mechanism = "attack did not complete (unscored)"
		return c
	}
	corrupted := canaryMutated || sentinelMutated
	c.corrupted = boolInt(corrupted)
	if corrupted {
		c.outcome = "SILENT_FAILURE"
		c.mechanism = "silent(state corruption confirmed by canary/sentinel)"
		c.score = 0
	} else {
		c.outcome = "SILENT_UB"
		c.mechanism = "silent(unreported UB; no corruption observed)"
		c.score = 0
	}
	return c
}

func boolInt(v bool) int {
	if v {
		return 1
	}
	return 0
}

// -- Output ------------------------------------------------------------------

type probeReport struct {
	Name            string  `json:"name"`
	Track           string  `json:"track"`
	OutcomeClass    string  `json:"outcome_class"`
	Mechanism       string  `json:"mechanism"`
	ErrorDetected   *bool   `json:"error_detected"`
	ProgramSurvived *bool   `json:"program_survived"`
	StateCorrupted  *bool   `json:"state_corrupted"`
	CanaryIntact    *bool   `json:"canary_intact"`
	SentinelIntact  *bool   `json:"sentinel_intact"`
	CanaryBefore    *uint32 `json:"canary_before"`
	CanaryAfter     *uint32 `json:"canary_after"`
	SentinelBefore  *uint64 `json:"sentinel_before"`
	SentinelAfter   *uint64 `json:"sentinel_after"`
	AttackCompleted *bool   `json:"attack_completed"`
	Containment     bool    `json:"containment"`
	ContainmentNote string  `json:"containment_note"`
	Score           *int    `json:"score"`
}

type report struct {
	Test          string        `json:"test"`
	Language      string        `json:"language"`
	SchemaVersion string        `json:"schema_version"`
	Note          string        `json:"note"`
	Probes        []probeReport `json:"probes"`
	SafetyIndex   int           `json:"safety_index"`
}

func tbPtr(v int) *bool {
	if v < 0 {
		return nil
	}
	b := v > 0
	return &b
}

func u32Ptr(v uint32) *uint32 {
	if v == 0 {
		return nil
	}
	return &v
}

func u64Ptr(v uint64) *uint64 {
	if v == 0 {
		return nil
	}
	return &v
}

func main() {
	if len(os.Args) >= 3 && os.Args[1] == "-probe" {
		runProbeChild(os.Args[2])
		return
	}

	out := report{
		Test:          "t8-safety-probe",
		Language:      "Go",
		SchemaVersion: "2.0",
		Note:          "Each probe isolated in a re-executed child; canary/sentinel observations carried over stdout; parent classifies from evidence.",
	}
	total, scored := 0, 0
	for _, d := range probeDefs {
		r := runIsolated(d.name)
		c := classify(r.rc, r.obs)
		if c.score >= 0 {
			total += c.score
			scored++
		}
		pr := probeReport{
			Name:            d.name,
			Track:           d.track,
			OutcomeClass:    c.outcome,
			Mechanism:       c.mechanism,
			ErrorDetected:   tbPtr(c.errorDetected),
			ProgramSurvived: tbPtr(c.survived),
			StateCorrupted:  tbPtr(c.corrupted),
			CanaryIntact:    tbPtr(c.canaryIntact),
			SentinelIntact:  tbPtr(c.sentinelIntact),
			Containment:     false,
			ContainmentNote: "parent-observed execution",
		}
		if c.hasObs {
			pr.CanaryBefore = u32Ptr(c.obs.CanaryBefore)
			pr.CanaryAfter = u32Ptr(c.obs.CanaryAfter)
			pr.SentinelBefore = u64Ptr(c.obs.SentinelBefore)
			pr.SentinelAfter = u64Ptr(c.obs.SentinelAfter)
			ac := c.obs.AttackCompleted == 1
			pr.AttackCompleted = &ac
		} else {
			ac := true
			pr.AttackCompleted = &ac
		}
		if c.score >= 0 {
			s := c.score
			pr.Score = &s
		}
		out.Probes = append(out.Probes, pr)
	}
	if scored > 0 {
		out.SafetyIndex = total * 100 / (scored * 10)
	}
	data, _ := json.Marshal(out)
	fmt.Println(string(data))
}

