-- Reference implementation: TCP Packet Parser (Ada 2012)
-- Systems Arena — parses binary TCP headers, computes checksums.
-- Compile: gnatmake -O2 -o t4-packet t4-packet.adb -cargs -gnatQ

with Ada.Text_IO; use Ada.Text_IO;
with Ada.Real_Time; use Ada.Real_Time;
with Interfaces; use Interfaces;

procedure Main is
    package Float_IO is new Ada.Text_IO.Float_IO (Float);

    type Byte_Array is array (1 .. 40) of Unsigned_8;
    Packet : Byte_Array := (others => 0);

    function Compute_Checksum (Data : Byte_Array; Len : Integer) return Unsigned_16 is
        Sum : Unsigned_32 := 0;
        I   : Integer;
    begin
        I := Data'First;
        while I + 1 <= Data'First + Len - 1 loop
            Sum := Sum + Unsigned_32
              (Shift_Left (Unsigned_16 (Data (I)), 8) or Unsigned_16 (Data (I + 1)));
            I := I + 2;
        end loop;
        if (Len mod 2) = 1 then
            Sum := Sum + Unsigned_32
              (Shift_Left (Unsigned_16 (Data (Data'First + Len - 1)), 8));
        end if;
        while Shift_Right (Sum, 16) > 0 loop
            Sum := (Sum and 16#FFFF#) + Shift_Right (Sum, 16);
        end loop;
        return not Unsigned_16 (Sum and 16#FFFF#);
    end Compute_Checksum;

    procedure Parse_Packet
      (Data     : in     Byte_Array;
       Src_Port :    out Unsigned_16;
       Dst_Port :    out Unsigned_16;
       Seq_Num  :    out Unsigned_32;
       Ack_Num  :    out Unsigned_32;
       Flags    :    out Unsigned_8;
       Window   :    out Unsigned_16;
       Checksum :    out Unsigned_16;
       Urgent   :    out Unsigned_16)
    is
    begin
        Src_Port := Shift_Left (Unsigned_16 (Data (1)), 8)  or Unsigned_16 (Data (2));
        Dst_Port := Shift_Left (Unsigned_16 (Data (3)), 8)  or Unsigned_16 (Data (4));
        Seq_Num  := Shift_Left (Unsigned_32 (Data (5)), 24) or
                    Shift_Left (Unsigned_32 (Data (6)), 16) or
                    Shift_Left (Unsigned_32 (Data (7)), 8)  or
                    Unsigned_32 (Data (8));
        Ack_Num  := Shift_Left (Unsigned_32 (Data (9)), 24) or
                    Shift_Left (Unsigned_32 (Data (10)), 16) or
                    Shift_Left (Unsigned_32 (Data (11)), 8)  or
                    Unsigned_32 (Data (12));
        Flags    := Data (14);
        Window   := Shift_Left (Unsigned_16 (Data (15)), 8) or Unsigned_16 (Data (16));
        Checksum := Shift_Left (Unsigned_16 (Data (17)), 8) or Unsigned_16 (Data (18));
        Urgent   := Shift_Left (Unsigned_16 (Data (19)), 8) or Unsigned_16 (Data (20));
    end Parse_Packet;

    Start : Time;
    Elapsed : Time_Span;
    Ms : Float;
    Pps : Integer;

    Src, Dst, Win, Csum, Urg : Unsigned_16;
    Seq, Ack : Unsigned_32;
    Flags : Unsigned_8;
begin
    Packet (1)  := 16#1F#; Packet (2)  := 16#90#;  -- src port 8080
    Packet (3)  := 16#00#; Packet (4)  := 16#50#;  -- dst port 80
    Packet (5)  := 16#00#; Packet (6)  := 16#00#;
    Packet (7)  := 16#00#; Packet (8)  := 16#01#;  -- seq
    Packet (9)  := 16#00#; Packet (10) := 16#00#;
    Packet (11) := 16#00#; Packet (12) := 16#00#;  -- ack
    Packet (13) := 16#50#; -- data offset + reserved
    Packet (14) := 16#02#; -- SYN flag
    Packet (15) := 16#7F#; Packet (16) := 16#FF#; -- window
    Packet (17) := 16#00#; Packet (18) := 16#00#; -- checksum (computed)
    Packet (19) := 16#00#; Packet (20) := 16#00#; -- urgent

    Start := Clock;

    for I in 0 .. 999_999 loop
        Packet (5) := Unsigned_8 (Shift_Right (Unsigned_32 (I), 24) and 16#FF#);
        Packet (6) := Unsigned_8 (Shift_Right (Unsigned_32 (I), 16) and 16#FF#);
        Packet (7) := Unsigned_8 (Shift_Right (Unsigned_32 (I), 8)  and 16#FF#);
        Packet (8) := Unsigned_8 (Unsigned_32 (I) and 16#FF#);

        declare
            Ck : Unsigned_16 := Compute_Checksum (Packet, 20);
        begin
            Packet (17) := Unsigned_8 (Shift_Right (Ck, 8) and 16#FF#);
            Packet (18) := Unsigned_8 (Ck and 16#FF#);
        end;

        Parse_Packet (Packet, Src, Dst, Seq, Ack, Flags, Win, Csum, Urg);
    end loop;

    Elapsed := Clock - Start;
    Ms := Float (To_Duration (Elapsed)) * 1000.0;
    if Ms = 0.0 then
        Ms := 0.001;
    end if;
    Pps := Integer (1_000_000.0 / (Ms / 1000.0));

    Put ("{""op"":""packet-parse"",""packets"":1000000,""time_ms"":");
    Float_IO.Put (Ms, Fore => 0, Aft => 2, Exp => 0);
    Put (",""pps"":");
    Put (Integer'Image (Pps));
    Put_Line ("}");
end Main;

