-- Reference implementation: B-Tree File Index (Ada 2012)
-- Systems Arena — ordered key-value store.
-- Compile: gnatmake -O2 -o t5-btree t5-btree.adb -cargs -gnatQ

with Ada.Text_IO; use Ada.Text_IO;
with Ada.Real_Time; use Ada.Real_Time;

procedure Main is
    package Float_IO is new Ada.Text_IO.Float_IO (Float);

    ORDER       : constant := 4;
    MAX_KEYS    : constant := ORDER - 1;
    MAX_CHILDREN : constant := ORDER;
    NODE_POOL_SIZE : constant := 10000;

    type Entry_Array is array (1 .. MAX_KEYS) of Long_Long_Integer;
    type Child_Array is array (1 .. MAX_CHILDREN) of Long_Long_Integer;

    type BTreeNode is record
        Num_Keys      : Integer := 0;
        Is_Leaf       : Boolean := True;
        Parent_Offset : Long_Long_Integer := 0;
        Keys          : Entry_Array := (others => 0);
        Values        : Entry_Array := (others => 0);
        Children      : Child_Array := (others => -1);
    end record;

    type Node_Pool_Array is array (1 .. NODE_POOL_SIZE) of BTreeNode;
    Node_Pool : Node_Pool_Array;
    Pool_Idx  : Integer := 0;

    function Alloc_Node return Integer is
    begin
        if Pool_Idx >= NODE_POOL_SIZE then
            return -1;
        end if;
        Pool_Idx := Pool_Idx + 1;
        Node_Pool (Pool_Idx) := (Num_Keys => 0, Is_Leaf => True,
                                 Parent_Offset => 0, Keys => (others => 0),
                                 Values => (others => 0), Children => (others => -1));
        return Pool_Idx;
    end Alloc_Node;

    function Btree_Search
      (Node_Idx : Integer;
       Key      : Long_Long_Integer) return Long_Long_Integer
    is
        Node : BTreeNode renames Node_Pool (Node_Idx);
        I : Integer := 1;
    begin
        while I <= Node.Num_Keys and then Key > Node.Keys (I) loop
            I := I + 1;
        end loop;
        if I <= Node.Num_Keys and then Key = Node.Keys (I) then
            return Node.Values (I);
        end if;
        return -1;
    end Btree_Search;

    procedure Btree_Insert_Nonfull
      (Node_Idx : Integer;
       Key      : Long_Long_Integer;
       Value    : Long_Long_Integer)
    is
        Node : BTreeNode renames Node_Pool (Node_Idx);
        I : Integer;
    begin
        if Node.Num_Keys >= MAX_KEYS then
            return;
        end if;
        I := Node.Num_Keys;
        while I >= 1 and then Key < Node.Keys (I) loop
            Node.Keys (I + 1)   := Node.Keys (I);
            Node.Values (I + 1) := Node.Values (I);
            I := I - 1;
        end loop;
        Node.Keys (I + 1)   := Key;
        Node.Values (I + 1) := Value;
        Node.Num_Keys := Node.Num_Keys + 1;
    end Btree_Insert_Nonfull;

    Start : Time;
    Elapsed : Time_Span;
    Ms : Float;
    Root_Idx : Integer;
    Found : Integer := 0;
    Val : Long_Long_Integer;
begin
    Start := Clock;

    Root_Idx := Alloc_Node;
    if Root_Idx = -1 then
        Put_Line ("ERROR: out of node pool");
        return;
    end if;

    for I in 0 .. 49999 loop
        Btree_Insert_Nonfull (Root_Idx, Long_Long_Integer (I) * 3,
                              Long_Long_Integer (I) * 7);
    end loop;

    for I in 0 .. 19999 loop
        Val := Btree_Search (Root_Idx, Long_Long_Integer (I) * 5);
        if Val /= -1 then
            Found := Found + 1;
        end if;
    end loop;

    Elapsed := Clock - Start;
    Ms := Float (To_Duration (Elapsed)) * 1000.0;

    Put ("{""op"":""btree"",""inserted"":50000,""searched"":20000,""found"":");
    Put (Integer'Image (Found));
    Put (",""time_ms"":");
    Float_IO.Put (Ms, Fore => 0, Aft => 2, Exp => 0);
    Put_Line ("}");
end Main;

