-- t8-safety-probe -- Language Safety Index (Ada), schema 2.0 observed evidence
--
-- P1.1 (hardening plan): 12 probes, each isolated in a forked child through
-- POSIX fork/pipe bindings (pragma Import, the same libc the C fixture uses);
-- the canary/sentinel guards live in a Volatile type, the child carries the
-- observation to the parent over a pipe, and the parent classifies from it.
--
-- Compiled with -O2 -gnata (checks on): constraint violations raise exceptions
-- and surface as runtime panics; raw address faults terminate the child with
-- a signal. Probes that are silent in checked mode are observed through the
-- canary/sentinel evidence, never assumed.
--
-- Ladder (contract scoring.safety_ladder): compile_error 10, runtime_panic 6,
-- os_crash 2, silent 0; INCONCLUSIVE is unscored (null), never "silent".

with Ada.Text_IO; use Ada.Text_IO;
with Ada.Strings.Unbounded; use Ada.Strings.Unbounded;
with Interfaces; use Interfaces;
with Interfaces.C;
with System;
with System.Storage_Elements; use System.Storage_Elements;
with Ada.Unchecked_Deallocation;
with Ada.Unchecked_Conversion;

procedure T8_Safety_Probe is

   -- -- POSIX bindings (libc is linked by the Ada runtime) -------------------

   function C_Fork return Interfaces.C.int;
   pragma Import (C, C_Fork, "fork");

   function C_Pipe (Fds : System.Address) return Interfaces.C.int;
   pragma Import (C, C_Pipe, "pipe");

   function C_Read
     (Fd : Interfaces.C.int; Buf : System.Address; Count : Interfaces.C.size_t)
      return Interfaces.C.long;
   pragma Import (C, C_Read, "read");

   function C_Write
     (Fd : Interfaces.C.int; Buf : System.Address; Count : Interfaces.C.size_t)
      return Interfaces.C.long;
   pragma Import (C, C_Write, "write");

   procedure C_Close (Fd : Interfaces.C.int);
   pragma Import (C, C_Close, "close");

   function C_Waitpid
     (Pid : Interfaces.C.int; Status : System.Address; Options : Interfaces.C.int)
      return Interfaces.C.int;
   pragma Import (C, C_Waitpid, "waitpid");

   procedure C_Exit (Status : Interfaces.C.int);
   pragma Import (C, C_Exit, "_exit");

   use type Interfaces.C.int;
   use type Interfaces.C.long;
   use type Interfaces.C.size_t;

   -- -- Types ----------------------------------------------------------------

   CANARY   : constant Unsigned_32 := 16#DEADBEEF#;
   SENTINEL : constant Unsigned_64 := 16#0BADF00D#;

   -- Observation carried from the child to the parent over a pipe. Layout is
   -- pinned by the representation clause so both ends agree exactly.
   type Obs is record
      Attack_Completed : Integer_32;
      Canary_Before    : Unsigned_32;
      Canary_After     : Unsigned_32;
      Sentinel_Before  : Unsigned_64;
      Sentinel_After   : Unsigned_64;
   end record;

   for Obs use record
      Attack_Completed at 0  range 0 .. 31;
      Canary_Before    at 4  range 0 .. 31;
      Canary_After     at 8  range 0 .. 31;
      Sentinel_Before  at 16 range 0 .. 63;
      Sentinel_After   at 24 range 0 .. 63;
   end record;
   for Obs'Size use 256;

   ZERO_OBS : constant Obs := (0, 0, 0, 0, 0);

   -- A guarded allocation: the dangerous operation must cross canary and
   -- sentinel. Volatile on the type keeps every component access observable
   -- (a plain read would be folded away at -O2 and the evidence would lie).
   type Buf_Array is array (1 .. 16) of Unsigned_8;

   type Guarded is record
      Buf      : Buf_Array;
      Canary   : Unsigned_32;
      Sentinel : Unsigned_64;
   end record
     with Volatile;

   for Guarded use record
      Buf      at 0  range 0 .. 127;
      Canary   at 16 range 0 .. 31;
      Sentinel at 24 range 0 .. 63;
   end record;
   for Guarded'Size use 256;

   type Guarded_All_Access is access all Guarded;
   type Int_All_Access is access all Integer;

   -- Observation slot, set in the probe child before the probe runs.
   G_Obs : access Obs := null;

   -- Sinks keep "defined but silent" computations from being optimised out.
   Sink_I : Integer := 0;
   Sink_C : Character := ' ';
   Sink_B : Unsigned_8 := 0;

   procedure Guard_Set (G : Guarded_All_Access) is
   begin
      for I in G.Buf'Range loop
         G.Buf (I) := 16#41#;
      end loop;
      G.Canary := CANARY;
      G.Sentinel := SENTINEL;
      if G_Obs /= null then
         G_Obs.Canary_Before := G.Canary;
         G_Obs.Sentinel_Before := G.Sentinel;
      end if;
   end Guard_Set;

   procedure Guard_Check (G : Guarded_All_Access) is
   begin
      if G_Obs /= null then
         G_Obs.Canary_After := G.Canary;
         G_Obs.Sentinel_After := G.Sentinel;
      end if;
   end Guard_Check;

   -- -- Probe implementations (every dangerous operation is intentional) -----

   procedure Probe_Use_After_Free is
      procedure Free is new Ada.Unchecked_Deallocation (Guarded, Guarded_All_Access);
      G  : Guarded_All_Access := new Guarded;
      G2 : Guarded_All_Access := G;
      X  : Unsigned_8;
   begin
      Guard_Set (G);
      Free (G);
      X := G2.Buf (1); -- USE AFTER FREE (read)
      Sink_B := X;
      Guard_Check (G2);
   end Probe_Use_After_Free;

   procedure Probe_Double_Free is
      procedure Free is new Ada.Unchecked_Deallocation (Guarded, Guarded_All_Access);
      G  : Guarded_All_Access := new Guarded;
      G2 : Guarded_All_Access := G;
   begin
      Guard_Set (G);
      Free (G);
      Free (G2); -- DOUBLE FREE (glibc abort)
      Guard_Check (G2);
   end Probe_Double_Free;

   procedure Probe_Buffer_Overflow is
      G : aliased Guarded;
      J : Integer := 200;
      X : Unsigned_8;
   begin
      Guard_Set (G'Unchecked_Access);
      X := G.Buf (J); -- OUT-OF-BOUNDS READ -> Constraint_Error
      Sink_B := X;
      Guard_Check (G'Unchecked_Access);
   end Probe_Buffer_Overflow;

   procedure Probe_Null_Deref is
      P : Int_All_Access := null;
      X : Integer;
   begin
      X := P.all; -- NULL DEREFERENCE
      Sink_I := X;
   end Probe_Null_Deref;

   procedure Probe_Integer_Overflow is
      G : aliased Guarded;
      A : Integer := Integer'Last;
      B : Integer;
   begin
      Guard_Set (G'Unchecked_Access);
      B := A + 1; -- SIGNED OVERFLOW -> Constraint_Error (-gnato)
      Sink_I := B;
      Guard_Check (G'Unchecked_Access);
   end Probe_Integer_Overflow;

   procedure Probe_Use_Of_Uninit is
      G : aliased Guarded;
      X : Integer;
   begin
      Guard_Set (G'Unchecked_Access);
      Sink_I := X; -- UNINITIALIZED read
      Guard_Check (G'Unchecked_Access);
   end Probe_Use_Of_Uninit;

   procedure Probe_Type_Confusion is
      G : aliased Guarded;
      F : Float := 3.14;
      function To_Int_Ptr is new Ada.Unchecked_Conversion (System.Address, Int_All_Access);
      P : Int_All_Access;
   begin
      Guard_Set (G'Unchecked_Access);
      P := To_Int_Ptr (F'Address); -- float bits read as Integer
      Sink_I := P.all;
      Guard_Check (G'Unchecked_Access);
   end Probe_Type_Confusion;

   procedure Probe_Stack_Overflow is
      Dummy : String (1 .. 4096) := (others => 'x');
      pragma Volatile (Dummy);
   begin
      Dummy (1) := 'y';
      if Dummy (1) = 'y' then
         Probe_Stack_Overflow;
      end if;
      Sink_C := Dummy (1); -- anti-TCO: volatile use after the call
   end Probe_Stack_Overflow;

   procedure Probe_Buffer_Overflow_Write is
      G : aliased Guarded;
   begin
      Guard_Set (G'Unchecked_Access);
      for I in 1 .. 256 loop
         G.Buf (I) := Unsigned_8 (I mod 256); -- OOB WRITE -> Constraint_Error
      end loop;
      Guard_Check (G'Unchecked_Access);
   end Probe_Buffer_Overflow_Write;

   procedure Probe_Invalid_Free is
      procedure Free is new Ada.Unchecked_Deallocation (Guarded, Guarded_All_Access);
      G : aliased Guarded;
      P : Guarded_All_Access := G'Unchecked_Access;
   begin
      Guard_Set (G'Unchecked_Access);
      Free (P); -- INVALID FREE of a stack address (glibc abort)
      Guard_Check (G'Unchecked_Access);
   end Probe_Invalid_Free;

   procedure Probe_Division_By_Zero is
      G : aliased Guarded;
      Z : Integer := 0;
   begin
      Guard_Set (G'Unchecked_Access);
      Sink_I := 1 / Z; -- DIVISION BY ZERO -> Constraint_Error
      Guard_Check (G'Unchecked_Access);
   end Probe_Division_By_Zero;

   procedure Probe_Invalid_Pointer is
      G : aliased Guarded;
      function To_Guarded_Ptr is new Ada.Unchecked_Conversion (System.Address, Guarded_All_Access);
      P : Guarded_All_Access;
   begin
      Guard_Set (G'Unchecked_Access);
      P := To_Guarded_Ptr (To_Address (16#DEADBEEF#)); -- bogus non-null pointer
      Sink_B := P.Buf (1);
      Guard_Check (G'Unchecked_Access);
   end Probe_Invalid_Pointer;

   -- -- Probe metadata -------------------------------------------------------

   type Probe_Proc is access procedure;

   type Probe_Entry is record
      Name  : Unbounded_String;
      Track : Unbounded_String;
      Fn    : Probe_Proc;
   end record;

   type Probe_Array is array (1 .. 12) of Probe_Entry;

   Probes : constant Probe_Array :=
     (1  => (To_Unbounded_String ("use-after-free"), To_Unbounded_String ("SAFE_SUBSET"),
             Probe_Use_After_Free'Access),
      2  => (To_Unbounded_String ("double-free"), To_Unbounded_String ("SAFE_SUBSET"),
             Probe_Double_Free'Access),
      3  => (To_Unbounded_String ("buffer-overflow"), To_Unbounded_String ("SAFE_SUBSET"),
             Probe_Buffer_Overflow'Access),
      4  => (To_Unbounded_String ("null-deref"), To_Unbounded_String ("FAULT_CONTAINMENT"),
             Probe_Null_Deref'Access),
      5  => (To_Unbounded_String ("integer-overflow"), To_Unbounded_String ("UNSAFE_BOUNDARY"),
             Probe_Integer_Overflow'Access),
      6  => (To_Unbounded_String ("use-of-uninit"), To_Unbounded_String ("SAFE_SUBSET"),
             Probe_Use_Of_Uninit'Access),
      7  => (To_Unbounded_String ("type-confusion"), To_Unbounded_String ("UNSAFE_BOUNDARY"),
             Probe_Type_Confusion'Access),
      8  => (To_Unbounded_String ("stack-overflow"), To_Unbounded_String ("FAULT_CONTAINMENT"),
             Probe_Stack_Overflow'Access),
      9  => (To_Unbounded_String ("buffer-overflow-write"), To_Unbounded_String ("SAFE_SUBSET"),
             Probe_Buffer_Overflow_Write'Access),
      10 => (To_Unbounded_String ("invalid-free"), To_Unbounded_String ("UNSAFE_BOUNDARY"),
             Probe_Invalid_Free'Access),
      11 => (To_Unbounded_String ("division-by-zero"), To_Unbounded_String ("FAULT_CONTAINMENT"),
             Probe_Division_By_Zero'Access),
      12 => (To_Unbounded_String ("invalid-pointer"), To_Unbounded_String ("UNSAFE_BOUNDARY"),
             Probe_Invalid_Pointer'Access));

   -- -- Isolation + classification -------------------------------------------

   type Run_Result is record
      Rc  : Integer;
      Has : Boolean;
      O   : Obs;
   end record;

   function Run_Isolated (Fn : Probe_Proc) return Run_Result is
      Fds   : array (0 .. 1) of aliased Interfaces.C.int;
      St    : aliased Unsigned_32 := 0;
      Child : Interfaces.C.int;
      N     : Interfaces.C.long;
   begin
      if C_Pipe (Fds (0)'Address) /= 0 then
         return (Rc => -1001, Has => False, O => ZERO_OBS);
      end if;
      Child := C_Fork;
      if Child = 0 then
         -- Child: observe the probe, carry the evidence to the parent, exit.
         declare
            O : aliased Obs := ZERO_OBS;
         begin
            C_Close (Fds (0));
            G_Obs := O'Unchecked_Access;
            Fn.all;
            O.Attack_Completed := 1;
            N := C_Write (Fds (1), O'Address, Obs'Size / 8);
            C_Close (Fds (1));
            C_Exit (0);
         end;
      end if;
      C_Close (Fds (1));
      declare
         O : aliased Obs := ZERO_OBS;
         W : Interfaces.C.int;
      begin
         N := C_Read (Fds (0), O'Address, Obs'Size / 8);
         C_Close (Fds (0));
         W := C_Waitpid (Child, St'Address, 0);
         pragma Unreferenced (W);
         if (St and 16#7F#) /= 0 and then (St and 16#7F#) /= 16#7F# then
            return (Rc => Integer (St and 16#7F#), Has => False, O => ZERO_OBS);
         end if;
         if (St / 256) mod 256 /= 0 then
            return (Rc => -Integer ((St / 256) mod 256), Has => False, O => ZERO_OBS);
         end if;
         if N /= Interfaces.C.long (Obs'Size / 8) then
            return (Rc => -1000, Has => False, O => ZERO_OBS); -- exit 0 without observation
         end if;
         return (Rc => 0, Has => True, O => O);
      end;
   end Run_Isolated;

   type Classified is record
      Outcome        : Unbounded_String;
      Mech           : Unbounded_String;
      Error_Detected : Integer;
      Survived       : Integer;
      Corrupted      : Integer;
      Canary_Intact  : Integer;
      Sentinel_Intact : Integer;
      Has_Obs        : Boolean;
      Score          : Integer;
      O              : Obs;
   end record;

   function Img (V : Integer) return String is
      S : constant String := Integer'Image (V);
   begin
      if S (S'First) = ' ' then
         return S (S'First + 1 .. S'Last);
      end if;
      return S;
   end Img;

   function Classify (R : Run_Result) return Classified is
      C : Classified :=
        (Outcome => To_Unbounded_String ("INCONCLUSIVE"),
         Mech => Null_Unbounded_String,
         Error_Detected => -1, Survived => -1, Corrupted => -1,
         Canary_Intact => -1, Sentinel_Intact => -1,
         Has_Obs => False, Score => -1, O => ZERO_OBS);
      Canary_Mutated   : Boolean;
      Sentinel_Mutated : Boolean;
      Corrupted        : Boolean;
   begin
      if R.Rc > 0 then
         C.Outcome := To_Unbounded_String ("OS_CRASH");
         C.Mech := To_Unbounded_String ("os_crash(signal " & Img (R.Rc) & ")");
         C.Error_Detected := 1;
         C.Survived := 0;
         C.Corrupted := 0;
         C.Score := 2;
         return C;
      end if;
      if R.Rc < 0 and then R.Rc /= -1000 then
         C.Outcome := To_Unbounded_String ("RUNTIME_PANIC");
         C.Mech := To_Unbounded_String ("runtime_panic(exit " & Img (-R.Rc) & ")");
         C.Error_Detected := 1;
         C.Survived := 0;
         C.Corrupted := 0;
         C.Score := 6;
         return C;
      end if;
      if not R.Has then
         C.Mech := To_Unbounded_String ("exit 0 without observation (unscored)");
         return C;
      end if;
      C.Has_Obs := True;
      C.O := R.O;
      Canary_Mutated := R.O.Canary_Before /= R.O.Canary_After;
      Sentinel_Mutated := R.O.Sentinel_Before /= R.O.Sentinel_After;
      C.Canary_Intact := (if Canary_Mutated then 0 else 1);
      C.Sentinel_Intact := (if Sentinel_Mutated then 0 else 1);
      C.Error_Detected := 0;
      C.Survived := 1;
      if R.O.Attack_Completed /= 1 then
         C.Mech := To_Unbounded_String ("attack did not complete (unscored)");
         return C;
      end if;
      Corrupted := Canary_Mutated or Sentinel_Mutated;
      C.Corrupted := (if Corrupted then 1 else 0);
      if Corrupted then
         C.Outcome := To_Unbounded_String ("SILENT_FAILURE");
         C.Mech := To_Unbounded_String ("silent(state corruption confirmed by canary/sentinel)");
         C.Score := 0;
      else
         C.Outcome := To_Unbounded_String ("SILENT_UB");
         C.Mech := To_Unbounded_String ("silent(unreported UB; no corruption observed)");
         C.Score := 0;
      end if;
      return C;
   end Classify;

   function TF (V : Integer) return String is
   begin
      if V < 0 then
         return "null";
      elsif V > 0 then
         return "true";
      else
         return "false";
      end if;
   end TF;

   procedure Put_U32_Or_Null (V : Unsigned_32) is
   begin
      if V = 0 then
         Put ("null");
      else
         Put (Unsigned_32'Image (V));
      end if;
   end Put_U32_Or_Null;

   procedure Put_U64_Or_Null (V : Unsigned_64) is
   begin
      if V = 0 then
         Put ("null");
      else
         Put (Unsigned_64'Image (V));
      end if;
   end Put_U64_Or_Null;

   Total  : Integer := 0;
   Scored : Integer := 0;
   Index  : Integer := 0;

begin
   -- Build the whole report and print it once, after every fork has
   -- completed: stdout stays untouched across fork(), so no child can
   -- inherit a partial buffer and corrupt the JSON.
   Put ("{""test"":""t8-safety-probe"",""language"":""Ada"",""schema_version"":""2.0"",");
   Put ("""note"":""Each probe isolated in a forked child; canary/sentinel observations carried over a pipe; parent classifies from evidence."",""probes"":[");
