/**
 * Reference implementation: Buddy Memory Allocator (C)
 * Systems Arena -- measures raw execution speed, memory usage, binary size.
 * Optimized for clarity and correctness, not competition tricks.
 */
#include <stddef.h>
#include <stdint.h>
#include <stdbool.h>
#include <stdlib.h>
#include <string.h>
#include <stdio.h>

#define POOL_SIZE (1024 * 1024)  // 1MB
#define MIN_BLOCK 64
#define MAX_ORDER 14  // 2^14 * 64 = 1MB

typedef struct Block {
    bool free;
    size_t order;
    struct Block *next;
} Block;

static unsigned char pool[POOL_SIZE] __attribute__((aligned(64)));
static Block *free_lists[MAX_ORDER + 1];
static int initialized = 0;

static size_t order_for_size(size_t size) {
    size_t block_size = MIN_BLOCK;
    size_t order = 0;
    while (block_size < size + sizeof(Block)) {
        block_size <<= 1;
        order++;
    }
    return order > MAX_ORDER ? MAX_ORDER : order;
}

static size_t block_size_for_order(size_t order) {
    return MIN_BLOCK << order;
}

static Block *split_block(size_t order) {
    if (order > MAX_ORDER) return NULL;
    if (free_lists[order]) {
        Block *block = free_lists[order];
        free_lists[order] = block->next;
        block->free = false;
        return block;
    }
    if (order == MAX_ORDER) return NULL;
    Block *bigger = split_block(order + 1);
    if (!bigger) return NULL;
    size_t half = block_size_for_order(order);
    Block *buddy = (Block *)((unsigned char *)bigger + half);
    buddy->free = true;
    buddy->order = order;
    buddy->next = free_lists[order];
    free_lists[order] = buddy;
    bigger->free = false;
    bigger->order = order;
    return bigger;
}

void buddy_init(void) {
    if (initialized) return;
    memset(pool, 0, POOL_SIZE);
    memset(free_lists, 0, sizeof(free_lists));
    Block *root = (Block *)pool;
    root->free = true;
    root->order = MAX_ORDER;
    root->next = NULL;
    free_lists[MAX_ORDER] = root;
    initialized = 1;
}

void *buddy_alloc(size_t size) {
    if (!initialized) buddy_init();
    if (size == 0) return NULL;
    size_t order = order_for_size(size);
    Block *block = split_block(order);
    if (!block) return NULL;
    return (unsigned char *)block + sizeof(Block);
}

void buddy_free(void *ptr) {
    if (!ptr) return;
    Block *block = (Block *)((unsigned char *)ptr - sizeof(Block));
    block->free = true;
    // Coalesce with buddy
    while (block->order < MAX_ORDER) {
        size_t bsize = block_size_for_order(block->order);
        uintptr_t addr = (uintptr_t)block - (uintptr_t)pool;
        uintptr_t buddy_addr = addr ^ bsize;
        if (buddy_addr + bsize > POOL_SIZE) break;
        Block *buddy = (Block *)(pool + buddy_addr);
        if (!buddy->free || buddy->order != block->order) break;
        // Remove buddy from free list
        Block **prev = &free_lists[block->order];
        while (*prev && *prev != buddy) prev = &(*prev)->next;
        if (*prev) *prev = buddy->next;
        // Merge into larger block
        block = addr < buddy_addr ? block : buddy;
        block->order++;
    }
    block->next = free_lists[block->order];
    free_lists[block->order] = block;
}

// Benchmark entry point -- alloc/free stress test
int main(void) {
    buddy_init();
    #define N 10000
    void *ptrs[N];
    // Allocate blocks of random sizes
    for (int i = 0; i < N; i++) {
        size_t sz = 64 + (i * 997) % 4096;
        ptrs[i] = buddy_alloc(sz);
    }
    // Free half
    for (int i = 0; i < N; i += 2) buddy_free(ptrs[i]);
    // Re-allocate
    for (int i = 0; i < N; i += 2) {
        size_t sz = 128 + (i * 503) % 2048;
        ptrs[i] = buddy_alloc(sz);
    }
    // Free all
    for (int i = 0; i < N; i++) buddy_free(ptrs[i]);
    printf("OK\n");
    return 0;
}

