/**
 * Reference implementation: TCP Packet Parser (C)
 * Systems Arena -- parses binary TCP headers and measures throughput.
 * Measures: execution speed, memory usage, binary size.
 */
#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <arpa/inet.h>

typedef struct __attribute__((packed)) {
    uint16_t src_port;
    uint16_t dst_port;
    uint32_t seq_num;
    uint32_t ack_num;
    uint8_t  data_offset:4;
    uint8_t  reserved:3;
    uint8_t  ns:1;
    uint8_t  flags;
    uint16_t window;
    uint16_t checksum;
    uint16_t urgent_ptr;
} TcpHeader;

int parse_packet(const uint8_t *data, size_t len, TcpHeader *hdr) {
    if (len < 20) return -1;
    memcpy(hdr, data, 20);
    hdr->src_port = ntohs(hdr->src_port);
    hdr->dst_port = ntohs(hdr->dst_port);
    hdr->seq_num = ntohl(hdr->seq_num);
    hdr->ack_num = ntohl(hdr->ack_num);
    hdr->window = ntohs(hdr->window);
    hdr->checksum = ntohs(hdr->checksum);
    hdr->urgent_ptr = ntohs(hdr->urgent_ptr);
    return 0;
}

uint16_t compute_checksum(const uint8_t *data, size_t len) {
    uint32_t sum = 0;
    for (size_t i = 0; i + 1 < len; i += 2) {
        sum += ((uint16_t)data[i] << 8) | data[i + 1];
    }
    if (len & 1) sum += (uint16_t)data[len - 1] << 8;
    while (sum >> 16) sum = (sum & 0xFFFF) + (sum >> 16);
    return (uint16_t)~sum;
}

int main(void) {
    clock_t start = clock();
    uint8_t packet[40] = {0};

    // Build a test TCP packet
    packet[0] = 0x1F; packet[1] = 0x90;  // src port 8080
    packet[2] = 0x00; packet[3] = 0x50;  // dst port 80
    packet[4] = 0x00; packet[5] = 0x00; packet[6] = 0x00; packet[7] = 0x01; // seq
    packet[8] = 0x00; packet[9] = 0x00; packet[10] = 0x00; packet[11] = 0x00;
    packet[12] = 0x50; // data offset + reserved
    packet[13] = 0x02; // SYN flag
    packet[14] = 0x7F; packet[15] = 0xFF; // window
    packet[16] = 0x00; packet[17] = 0x00; // checksum (compute below)
    packet[18] = 0x00; packet[19] = 0x00; // urgent

    // Benchmark: parse 1 million packets
    TcpHeader hdr;
    for (int i = 0; i < 1000000; i++) {
        packet[4] = (i >> 24) & 0xFF; // vary seq number
        packet[5] = (i >> 16) & 0xFF;
        packet[6] = (i >> 8) & 0xFF;
        packet[7] = i & 0xFF;
        uint16_t csum = compute_checksum(packet, 20);
        packet[16] = (csum >> 8) & 0xFF;
        packet[17] = csum & 0xFF;
        parse_packet(packet, 20, &hdr);
    }

    double elapsed = (double)(clock() - start) / CLOCKS_PER_SEC * 1000.0;
    printf("{\"op\":\"packet-parse\",\"packets\":1000000,\"time_ms\":%.2f,\"pps\":%.0f}\n",
           elapsed, 1000000000.0 / (elapsed > 0 ? elapsed : 1));
    return 0;
}

