// Reference implementation: Buddy Memory Allocator (C++)
// Systems Arena -- measures raw execution speed, memory, binary size.
#include <cstddef>
#include <cstdint>
#include <algorithm>
#include <vector>
#include <iostream>

class BuddyAllocator {
    static constexpr size_t POOL_SIZE = 1 << 20; // 1MB
    static constexpr size_t MIN_BLOCK = 64;
    static constexpr size_t MAX_ORDER = 14;

    struct Block {
        bool free = true;
        size_t order = 0;
        Block *next = nullptr;
    };

    alignas(64) unsigned char pool[POOL_SIZE]{};
    Block *free_lists[MAX_ORDER + 1]{};
    bool initialized = false;

    size_t order_for_size(size_t size) const {
        size_t block_size = MIN_BLOCK, order = 0;
        while (block_size < size + sizeof(Block) && order < MAX_ORDER) {
            block_size <<= 1; order++;
        }
        return order;
    }

    Block *split_block(size_t order) {
        if (order > MAX_ORDER) return nullptr;
        if (free_lists[order]) {
            auto *b = free_lists[order];
            free_lists[order] = b->next;
            b->free = false;
            return b;
        }
        if (order == MAX_ORDER) return nullptr;
        auto *bigger = split_block(order + 1);
        if (!bigger) return nullptr;
        size_t half = MIN_BLOCK << order;
        auto *buddy = reinterpret_cast<Block *>(reinterpret_cast<unsigned char *>(bigger) + half);
        buddy->free = true;
        buddy->order = order;
        buddy->next = free_lists[order];
        free_lists[order] = buddy;
        bigger->free = false;
        bigger->order = order;
        return bigger;
    }

public:
    void init() {
        if (initialized) return;
        std::fill(std::begin(pool), std::end(pool), 0);
        std::fill(std::begin(free_lists), std::end(free_lists), nullptr);
        auto *root = reinterpret_cast<Block *>(pool);
        root->free = true;
        root->order = MAX_ORDER;
        free_lists[MAX_ORDER] = root;
        initialized = true;
    }

    void *alloc(size_t size) {
        if (!initialized) init();
        if (size == 0) return nullptr;
        auto *block = split_block(order_for_size(size));
        return block ? reinterpret_cast<unsigned char *>(block) + sizeof(Block) : nullptr;
    }

    void free(void *ptr) {
        if (!ptr) return;
        auto *block = reinterpret_cast<Block *>(static_cast<unsigned char *>(ptr) - sizeof(Block));
        block->free = true;
        while (block->order < MAX_ORDER) {
            size_t bsize = MIN_BLOCK << block->order;
            uintptr_t addr = reinterpret_cast<uintptr_t>(block) - reinterpret_cast<uintptr_t>(pool);
            uintptr_t buddy_addr = addr ^ bsize;
            if (buddy_addr + bsize > POOL_SIZE) break;
            auto *buddy = reinterpret_cast<Block *>(pool + buddy_addr);
            if (!buddy->free || buddy->order != block->order) break;
            Block **prev = &free_lists[block->order];
            while (*prev && *prev != buddy) prev = &(*prev)->next;
            if (*prev) *prev = buddy->next;
            if (addr < buddy_addr) block->order++; else { block = buddy; block->order++; }
        }
        block->next = free_lists[block->order];
        free_lists[block->order] = block;
    }
};

int main() {
    BuddyAllocator ba;
    ba.init();
    constexpr int N = 10000;
    void *ptrs[N];
    for (int i = 0; i < N; i++) ptrs[i] = ba.alloc(64 + (i * 997) % 4096);
    for (int i = 0; i < N; i += 2) ba.free(ptrs[i]);
    for (int i = 0; i < N; i += 2) ptrs[i] = ba.alloc(128 + (i * 503) % 2048);
    for (int i = 0; i < N; i++) ba.free(ptrs[i]);
    std::cout << "OK\n";
}

