/**
 * Reference implementation: Hot-Reload Module Loader (C++)
 * Systems Arena -- measures execution speed, memory usage, binary size.
 *
 * Real dynamic module loading: every cycle opens a shared library
 * (dlopen -> RTLD_NOW), resolves the exported function (dlsym), calls it
 * 100 times, then hot-reloads (a fresh dlopen replaces the old handle) and
 * unloads it (dlclose). The workload is identical for every language:
 * libc.so.6 / abs, 1000 cycles x 100 calls, deterministic arguments.
 */
#include <chrono>
#include <cstdio>
#include <dlfcn.h>

constexpr int kCycles = 1000;
constexpr int kCallsPerCycle = 100;
constexpr const char *kModulePath = "libc.so.6";
constexpr const char *kSymbolName = "abs";

using AbsFn = int (*)(int);

int main() {
    auto start = std::chrono::steady_clock::now();

    long long checksum = 0;
    for (int i = 0; i < kCycles; ++i) {
        void *handle = dlopen(kModulePath, RTLD_NOW);
        if (!handle) {
            std::fprintf(stderr, "dlopen failed: %s\n", dlerror());
            return 1;
        }
        auto fn = reinterpret_cast<AbsFn>(dlsym(handle, kSymbolName));
        if (!fn) {
            std::fprintf(stderr, "dlsym failed: %s\n", dlerror());
            dlclose(handle);
            return 1;
        }
        for (int j = 0; j < kCallsPerCycle; ++j) {
            int arg = (i * 31 + j * 17) % 1000 - 500;
            checksum += fn(arg);
        }
        void *fresh = dlopen(kModulePath, RTLD_NOW);
        if (!fresh) {
            std::fprintf(stderr, "reload dlopen failed: %s\n", dlerror());
            dlclose(handle);
            return 1;
        }
        dlclose(handle);
        dlclose(fresh);
    }

    auto end = std::chrono::steady_clock::now();
    double ms = std::chrono::duration<double, std::milli>(end - start).count();
    std::printf("{\"op\":\"hot-reload\",\"cycles\":%d,\"calls\":%d,\"checksum\":%lld,\"time_ms\":%.2f}\n",
                kCycles, kCycles * kCallsPerCycle, checksum, ms);
    return 0;
}

