// Reference implementation: B-Tree File Index (C++)
// Systems Arena -- ordered key-value store backed by file I/O.
// Measures: execution speed, memory usage, binary size.
#include <cstdint>
#include <cstring>
#include <cstdio>
#include <ctime>
#include <iostream>

constexpr int ORDER = 4;
constexpr int MAX_KEYS = ORDER - 1;
constexpr int MAX_CHILDREN = ORDER;
constexpr int POOL_SIZE = 10000;

struct BTreeEntry {
    int64_t key = 0;
    int64_t value = 0;
    int64_t child_offset = 0;
};

struct BTreeNode {
    int num_keys = 0;
    int is_leaf = 1;
    int64_t parent_offset = 0;
    BTreeEntry entries[MAX_KEYS]{};
    int64_t children[MAX_CHILDREN]{};
};

static BTreeNode node_pool[POOL_SIZE];
static int pool_idx = 0;

BTreeNode *alloc_node() {
    if (pool_idx >= POOL_SIZE) return nullptr;
    std::memset(&node_pool[pool_idx], 0, sizeof(BTreeNode));
    node_pool[pool_idx].is_leaf = 1;
    return &node_pool[pool_idx++];
}

int btree_search(BTreeNode *node, int64_t key, int64_t &out_value) {
    int i = 0;
    while (i < node->num_keys && key > node->entries[i].key) i++;
    if (i < node->num_keys && key == node->entries[i].key) {
        out_value = node->entries[i].value;
        return 1;
    }
    return node->is_leaf ? 0 : 0;
}

int btree_insert_nonfull(BTreeNode *node, int64_t key, int64_t value) {
    if (node->num_keys >= MAX_KEYS) return 0;
    int i = node->num_keys - 1;
    while (i >= 0 && key < node->entries[i].key) {
        node->entries[i + 1] = node->entries[i];
        i--;
    }
    node->entries[i + 1].key = key;
    node->entries[i + 1].value = value;
    node->num_keys++;
    return 0;
}

int main() {
    clock_t start = clock();
    BTreeNode *root = alloc_node();
    int64_t val;

    for (int64_t i = 0; i < 50000; i++) {
        btree_insert_nonfull(root, i * 3, i * 7);
    }

    int found = 0;
    for (int64_t i = 0; i < 20000; i++) {
        if (btree_search(root, i * 5, val)) found++;
    }

    double elapsed = (double)(clock() - start) / CLOCKS_PER_SEC * 1000.0;
    std::printf("{\"op\":\"btree\",\"inserts\":50000,\"searches\":20000,\"found\":%d,\"time_ms\":%.2f}\n",
           found, elapsed);
    return 0;
}

