// SPDX-License-Identifier: MIT OR Apache-2.0

/*
 * t8-safety-probe -- Language Safety Index (C++), schema 2.0 observed evidence
 *
 * P1.1 (hardening plan): same harness design as the C fixture -- 12 probes,
 * each fork-isolated, canary/sentinel guards (volatile so -O2 cannot elide the
 * observation), evidence carried from the probe child to the parent over a
 * pipe, parent-side classification. C++ specifics: new/delete instead of
 * malloc/free, reinterpret_cast for the type-confusion probe.
 *
 * Ladder (contract scoring.safety_ladder): compile_error 10, runtime_panic 6,
 * os_crash 2, silent 0; INCONCLUSIVE is unscored (null), never "silent".
 */
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <csignal>
#include <unistd.h>
#include <sys/wait.h>
#include <climits>
#include <cstdint>

#define CANARY 0xDEADBEEFu
#define SENTINEL 0x0BADF00Dull

typedef struct {
    int attack_completed;
    uint32_t canary_before;
    uint32_t canary_after;
    uint64_t sentinel_before;
    uint64_t sentinel_after;
} Obs;

typedef struct {
    volatile char buf[16];
    volatile uint32_t canary;
    volatile uint64_t sentinel;
} Guarded;

static Obs* g_obs = NULL;
static volatile int recursion_depth = 0;

static void guard_set(Guarded* g) {
    for (int i = 0; i < 16; i++) g->buf[i] = 0x41;
    g->canary = CANARY;
    g->sentinel = SENTINEL;
    if (g_obs) {
        g_obs->canary_before = g->canary;
        g_obs->sentinel_before = g->sentinel;
    }
}

static void guard_check(Guarded* g) {
    if (g_obs) {
        g_obs->canary_after = g->canary;
        g_obs->sentinel_after = g->sentinel;
    }
}

/* -- Probe implementations --------------------------------------------- */

static void probe_use_after_free(void) {
    Guarded* g = new Guarded();
    guard_set(g);
    delete g;
    volatile char x = g->buf[0]; /* USE AFTER FREE (read) */
    (void)x;
    guard_check(g);
}

static void probe_double_free(void) {
    Guarded* g = new Guarded();
    guard_set(g);
    delete g;
    delete g; /* DOUBLE FREE */
    guard_check(g);
}

static void probe_buffer_overflow(void) {
    Guarded* g = new Guarded();
    guard_set(g);
    volatile char x = g->buf[200]; /* OUT-OF-BOUNDS READ */
    (void)x;
    guard_check(g);
}

static void probe_null_deref(void) {
    volatile int* p = nullptr;
    volatile int x = *p; /* NULL DEREFERENCE */
    (void)x;
}

static void probe_integer_overflow(void) {
    Guarded g;
    guard_set(&g);
    volatile int a = INT_MAX;
    volatile int b = a + 1; /* SIGNED OVERFLOW -- UB */
    (void)b;
    guard_check(&g);
}

static void probe_use_of_uninit(void) {
    Guarded g;
    guard_set(&g);
    int x; /* UNINITIALIZED */
    volatile int y = x;
    (void)y;
    guard_check(&g);
}

static void probe_type_confusion(void) {
    Guarded g;
    guard_set(&g);
    float f = 3.14f;
    volatile int* ip = reinterpret_cast<volatile int*>(&f); /* reinterpret bits */
    volatile int confused = *ip;
    (void)confused;
    guard_check(&g);
}

static void probe_stack_overflow(void) {
    volatile char dummy[4096];
    dummy[0] = 1;
    recursion_depth++;
    probe_stack_overflow();
    (void)dummy[0]; /* anti-TCO */
}

static void probe_buffer_overflow_write(void) {
    Guarded* g = new Guarded();
    guard_set(g);
    for (int i = 0; i < 256; i++) g->buf[i] = (char)i; /* OOB WRITE over canary/sentinel */
    volatile char sink = g->buf[0];
    (void)sink;
    guard_check(g);
}

static void probe_invalid_free(void) {
    Guarded g;
    guard_set(&g);
    delete (Guarded*)&g; /* INVALID FREE of a stack address */
    guard_check(&g);
}

static void probe_division_by_zero(void) {
    Guarded g;
    guard_set(&g);
    volatile int z = 0;
    volatile int q = 1 / z; /* DIVISION BY ZERO */
    (void)q;
    guard_check(&g);
}

static void probe_invalid_pointer(void) {
    Guarded g;
    guard_set(&g);
    volatile int* p = reinterpret_cast<volatile int*>(0xdeadbeefULL);
    *p = 1;
    guard_check(&g);
}

/* -- Probe metadata ----------------------------------------------------- */

typedef struct {
    const char* name;
    const char* track;
    void (*fn)(void);
} ProbeDef;

static const ProbeDef PROBES[] = {
    { "use-after-free",        "SAFE_SUBSET",       probe_use_after_free },
    { "double-free",           "SAFE_SUBSET",       probe_double_free },
    { "buffer-overflow",       "SAFE_SUBSET",       probe_buffer_overflow },
    { "null-deref",            "FAULT_CONTAINMENT", probe_null_deref },
    { "integer-overflow",      "UNSAFE_BOUNDARY",   probe_integer_overflow },
    { "use-of-uninit",         "SAFE_SUBSET",       probe_use_of_uninit },
    { "type-confusion",        "UNSAFE_BOUNDARY",   probe_type_confusion },
    { "stack-overflow",        "FAULT_CONTAINMENT", probe_stack_overflow },
    { "buffer-overflow-write", "SAFE_SUBSET",       probe_buffer_overflow_write },
    { "invalid-free",          "UNSAFE_BOUNDARY",   probe_invalid_free },
    { "division-by-zero",      "FAULT_CONTAINMENT", probe_division_by_zero },
    { "invalid-pointer",       "UNSAFE_BOUNDARY",   probe_invalid_pointer },
};

/* -- Isolation + classification ----------------------------------------- */

static int run_isolated(void (*fn)(void), Obs* out) {
    int fds[2];
    memset(out, 0, sizeof(*out));
    if (pipe(fds) != 0) return -1001;
    fflush(stdout);
    fflush(stderr);
    pid_t pid = fork();
    if (pid == 0) {
        close(fds[0]);
        Obs obs;
        memset(&obs, 0, sizeof(obs));
        g_obs = &obs;
        fn();
        obs.attack_completed = 1;
        ssize_t w = write(fds[1], &obs, sizeof(obs));
        (void)w;
        close(fds[1]);
        _exit(0);
    }
    close(fds[1]);
    ssize_t n = read(fds[0], out, sizeof(*out));
    close(fds[0]);
    int status;
    waitpid(pid, &status, 0);
    if (WIFSIGNALED(status)) return WTERMSIG(status);
    if (WIFEXITED(status) && WEXITSTATUS(status) != 0) return -WEXITSTATUS(status);
    if (n != (ssize_t)sizeof(*out)) return -1000;
    return 0;
}

typedef struct {
    const char* outcome;
    char mechanism[64];
    int error_detected;
    int survived;
    int corrupted;
    int canary_intact;
    int sentinel_intact;
    int has_obs;
    int score;
    Obs obs;
} Classified;

static void classify(int rc, const Obs* obs, int got_obs, Classified* c) {
    memset(c, 0, sizeof(*c));
    c->score = -1;
    c->error_detected = -1;
    c->survived = -1;
    c->corrupted = -1;
    c->canary_intact = -1;
    c->sentinel_intact = -1;
    if (rc > 0) {
        c->outcome = "OS_CRASH";
        snprintf(c->mechanism, sizeof(c->mechanism), "os_crash(signal %d)", rc);
        c->error_detected = 1;
        c->survived = 0;
        c->corrupted = 0;
        c->score = 2;
        return;
    }
    if (rc < 0 && rc != -1000) {
        c->outcome = "RUNTIME_PANIC";
        snprintf(c->mechanism, sizeof(c->mechanism), "runtime_panic(exit %d)", -rc);
        c->error_detected = 1;
        c->survived = 0;
        c->corrupted = 0;
        c->score = 6;
        return;
    }
    if (!got_obs) {
        c->outcome = "INCONCLUSIVE";
        snprintf(c->mechanism, sizeof(c->mechanism), "exit 0 without observation (unscored)");
        return;
    }
    c->has_obs = 1;
    c->obs = *obs;
    int canary_mutated = obs->canary_before != obs->canary_after;
    int sentinel_mutated = obs->sentinel_before != obs->sentinel_after;
    c->canary_intact = canary_mutated ? 0 : 1;
    c->sentinel_intact = sentinel_mutated ? 0 : 1;
    c->error_detected = 0;
    c->survived = 1;
    if (!obs->attack_completed) {
        c->outcome = "INCONCLUSIVE";
        snprintf(c->mechanism, sizeof(c->mechanism), "attack did not complete (unscored)");
        return;
    }
    int corrupted = canary_mutated || sentinel_mutated;
    c->corrupted = corrupted;
    if (corrupted) {
        c->outcome = "SILENT_FAILURE";
        snprintf(c->mechanism, sizeof(c->mechanism), "silent(state corruption confirmed by canary/sentinel)");
        c->score = 0;
    } else {
        c->outcome = "SILENT_UB";
        snprintf(c->mechanism, sizeof(c->mechanism), "silent(unreported UB; no corruption observed)");
        c->score = 0;
    }
}

static const char* tb(int v) {
    return v < 0 ? "null" : (v ? "true" : "false");
}

static void print_uint_or_null(uint32_t v) {
    if (v == 0) printf("null"); else printf("%u", v);
}

static void print_ull_or_null(uint64_t v) {
    if (v == 0) printf("null"); else printf("%llu", (unsigned long long)v);
}

int main(void) {
    size_t count = sizeof(PROBES) / sizeof(PROBES[0]);
    printf("{\"test\":\"t8-safety-probe\",\"language\":\"C++\",\"schema_version\":\"2.0\",");
    printf("\"note\":\"Each probe isolated in a forked child; canary/sentinel observations carried over a pipe; parent classifies from evidence.\",\"probes\":[");
    long total = 0;
    int scored = 0;
    for (size_t i = 0; i < count; i++) {
        Obs obs;
        int rc = run_isolated(PROBES[i].fn, &obs);
        int got_obs = rc == 0;
        Classified c;
        classify(rc, &obs, got_obs, &c);
        if (c.score >= 0) { total += c.score; scored++; }
        if (i > 0) printf(",");
        printf("{\"name\":\"%s\",\"track\":\"%s\",\"outcome_class\":\"%s\",\"mechanism\":\"%s\",",
               PROBES[i].name, PROBES[i].track, c.outcome, c.mechanism);
        printf("\"error_detected\":%s,\"program_survived\":%s,\"state_corrupted\":%s,",
               tb(c.error_detected), tb(c.survived), tb(c.corrupted));
        printf("\"canary_intact\":%s,\"sentinel_intact\":%s,", tb(c.canary_intact), tb(c.sentinel_intact));
        printf("\"canary_before\":");
        print_uint_or_null(c.has_obs ? c.obs.canary_before : 0);
        printf(",\"canary_after\":");
        print_uint_or_null(c.has_obs ? c.obs.canary_after : 0);
        printf(",\"sentinel_before\":");
        print_ull_or_null(c.has_obs ? c.obs.sentinel_before : 0);
        printf(",\"sentinel_after\":");
        print_ull_or_null(c.has_obs ? c.obs.sentinel_after : 0);
        printf(",\"attack_completed\":%s,", c.has_obs ? tb(c.obs.attack_completed) : "true");
        printf("\"containment\":false,\"containment_note\":\"parent-observed execution\",");
        if (c.score < 0) printf("\"score\":null}");
        else printf("\"score\":%d}", c.score);
    }
    int index = scored > 0 ? (int)((total * 100) / (scored * 10)) : -1;
    printf("],\"safety_index\":%d}\n", index < 0 ? 0 : index);
    return 0;
}

