// Reference implementation: SPSC Concurrent Queue (Rust)
// Systems Arena -- lock-free single-producer single-consumer queue.

use std::sync::atomic::{AtomicUsize, Ordering};

struct SPSCQueue {
    head: AtomicUsize,
    tail: AtomicUsize,
    capacity: usize,
    buffer: Box<[i64]>,
}

impl SPSCQueue {
    fn new(capacity: usize) -> Self {
        let cap = capacity + 1;
        SPSCQueue {
            head: AtomicUsize::new(0),
            tail: AtomicUsize::new(0),
            capacity: cap,
            buffer: vec![0i64; cap].into_boxed_slice(),
        }
    }

    fn enqueue(&self, val: i64) -> bool {
        let tail = self.tail.load(Ordering::Relaxed);
        let next = (tail + 1) % self.capacity;
        if next == self.head.load(Ordering::Acquire) {
            return false;
        }
        unsafe {
            let buf = self.buffer.as_ptr() as *mut i64;
            *buf.add(tail) = val;
        }
        self.tail.store(next, Ordering::Release);
        true
    }

    fn dequeue(&self) -> Option<i64> {
        let head = self.head.load(Ordering::Relaxed);
        if head == self.tail.load(Ordering::Acquire) {
            return None;
        }
        let val = unsafe { *self.buffer.as_ptr().add(head) };
        self.head.store((head + 1) % self.capacity, Ordering::Release);
        Some(val)
    }
}

fn main() {
    let q = SPSCQueue::new(1000000);
    for i in 0..1000000i64 {
        q.enqueue(i);
    }
    for _ in 0..1000000 {
        q.dequeue();
    }
    println!("OK");
}

