// Copyright (c) 2026 Eleftherios Notas and The XIOM Authors
// SPDX-License-Identifier: MIT OR Apache-2.0

/*
 * Reference implementation: Hot-Reload Module Loader (Rust)
 * Systems Arena -- measures execution speed, memory usage, binary size.
 *
 * Real dynamic module loading through extern "C" dlopen/dlsym/dlclose
 * (no crates): every cycle opens a shared library, resolves the exported
 * function, calls it 100 times, then hot-reloads (a fresh dlopen replaces
 * the old handle) and unloads it. The workload is identical for every
 * language: libc.so.6 / abs, 1000 cycles x 100 calls, deterministic args.
 */

use std::ffi::CString;
use std::os::raw::{c_char, c_int, c_void};
use std::time::Instant;

extern "C" {
    fn dlopen(filename: *const c_char, flags: c_int) -> *mut c_void;
    fn dlsym(handle: *mut c_void, symbol: *const c_char) -> *mut c_void;
    fn dlclose(handle: *mut c_void) -> c_int;
}

const RTLD_NOW: c_int = 2;
const CYCLES: i32 = 1000;
const CALLS_PER_CYCLE: i32 = 100;

fn main() {
    let path = CString::new("libc.so.6").expect("module path");
    let symbol = CString::new("abs").expect("symbol name");

    let start = Instant::now();
    let mut checksum: i64 = 0;

    for i in 0..CYCLES {
        let handle = unsafe { dlopen(path.as_ptr(), RTLD_NOW) };
        if handle.is_null() {
            eprintln!("dlopen failed");
            std::process::exit(1);
        }
        let address = unsafe { dlsym(handle, symbol.as_ptr()) };
        if address.is_null() {
            eprintln!("dlsym failed");
            unsafe { dlclose(handle) };
            std::process::exit(1);
        }
        let abs_fn: unsafe extern "C" fn(c_int) -> c_int = unsafe { std::mem::transmute(address) };

        for j in 0..CALLS_PER_CYCLE {
            let arg = (i * 31 + j * 17) % 1000 - 500;
            checksum += unsafe { abs_fn(arg) } as i64;
        }

        let fresh = unsafe { dlopen(path.as_ptr(), RTLD_NOW) };
        if fresh.is_null() {
            eprintln!("reload dlopen failed");
            unsafe { dlclose(handle) };
            std::process::exit(1);
        }
        unsafe {
            dlclose(handle);
            dlclose(fresh);
        }
    }

    let ms = start.elapsed().as_secs_f64() * 1000.0;
    println!(
        "{{\"op\":\"hot-reload\",\"cycles\":{},\"calls\":{},\"checksum\":{},\"time_ms\":{:.2}}}",
        CYCLES,
        CYCLES * CALLS_PER_CYCLE,
        checksum,
        ms
    );
}

