// Reference implementation: TCP Packet Parser (Rust)
// Systems Arena -- parses binary TCP headers and measures throughput.
// Measures: execution speed, memory usage, binary size.

use std::time::Instant;

#[repr(C, packed)]
struct TcpHeader {
    src_port: u16,
    dst_port: u16,
    seq_num: u32,
    ack_num: u32,
    data_offset_reserved: u8,
    flags: u8,
    window: u16,
    checksum: u16,
    urgent_ptr: u16,
}

fn ntoh16(v: u16) -> u16 {
    v.to_be()
}

fn ntoh32(v: u32) -> u32 {
    v.to_be()
}

fn parse_packet(data: &[u8], hdr: &mut TcpHeader) -> Result<(), &'static str> {
    if data.len() < 20 {
        return Err("packet too short");
    }
    unsafe {
        std::ptr::copy_nonoverlapping(data.as_ptr(), hdr as *mut TcpHeader as *mut u8, 20);
    }
    hdr.src_port = ntoh16(hdr.src_port);
    hdr.dst_port = ntoh16(hdr.dst_port);
    hdr.seq_num = ntoh32(hdr.seq_num);
    hdr.ack_num = ntoh32(hdr.ack_num);
    hdr.window = ntoh16(hdr.window);
    hdr.checksum = ntoh16(hdr.checksum);
    hdr.urgent_ptr = ntoh16(hdr.urgent_ptr);
    Ok(())
}

fn compute_checksum(data: &[u8]) -> u16 {
    let mut sum: u32 = 0;
    let len = data.len();
    let mut i = 0;
    while i + 1 < len {
        sum += ((data[i] as u32) << 8) | data[i + 1] as u32;
        i += 2;
    }
    if len & 1 == 1 {
        sum += (data[len - 1] as u32) << 8;
    }
    while sum >> 16 != 0 {
        sum = (sum & 0xFFFF) + (sum >> 16);
    }
    !(sum as u16)
}

fn main() {
    let start = Instant::now();
    let mut packet: [u8; 40] = [0u8; 40];

    packet[0] = 0x1F; packet[1] = 0x90;
    packet[2] = 0x00; packet[3] = 0x50;
    packet[4] = 0x00; packet[5] = 0x00; packet[6] = 0x00; packet[7] = 0x01;
    packet[8] = 0x00; packet[9] = 0x00; packet[10] = 0x00; packet[11] = 0x00;
    packet[12] = 0x50;
    packet[13] = 0x02;
    packet[14] = 0x7F; packet[15] = 0xFF;
    packet[16] = 0x00; packet[17] = 0x00;
    packet[18] = 0x00; packet[19] = 0x00;

    let mut hdr = TcpHeader {
        src_port: 0, dst_port: 0, seq_num: 0, ack_num: 0,
        data_offset_reserved: 0, flags: 0, window: 0, checksum: 0, urgent_ptr: 0,
    };

    for i in 0..1000000 {
        packet[4] = ((i >> 24) & 0xFF) as u8;
        packet[5] = ((i >> 16) & 0xFF) as u8;
        packet[6] = ((i >> 8) & 0xFF) as u8;
        packet[7] = (i & 0xFF) as u8;
        let csum = compute_checksum(&packet[..20]);
        packet[16] = ((csum >> 8) & 0xFF) as u8;
        packet[17] = (csum & 0xFF) as u8;
        let _ = parse_packet(&packet[..20], &mut hdr);
    }

    let elapsed = start.elapsed().as_secs_f64() * 1000.0;
    let pps = if elapsed > 0.0 { 1_000_000_000.0 / elapsed } else { 0.0 };
    println!("{{\"op\":\"packet-parse\",\"packets\":1000000,\"time_ms\":{:.2},\"pps\":{:.0}}}", elapsed, pps);
}

