extern "C" {
    fn fork() -> i32;
    fn waitpid(pid: i32, status: *mut i32, options: i32) -> i32;
    fn pipe(fds: *mut i32) -> i32;
    fn read(fd: i32, buf: *mut u8, count: usize) -> isize;
    fn write(fd: i32, buf: *const u8, count: usize) -> isize;
    fn close(fd: i32) -> i32;
}

const CANARY: u32 = 0xDEADBEEF;
const SENTINEL: u64 = 0x0BADF00D;
const N_PROBES: usize = 12;

#[repr(C)]
#[derive(Clone, Copy, Default)]
struct Obs {
    attack_completed: i32,
    canary_before: u32,
    canary_after: u32,
    sentinel_before: u64,
    sentinel_after: u64,
}

#[repr(C)]
struct Guarded {
    buf: [u8; 16],
    canary: u32,
    sentinel: u64,
}

static mut OBS: *mut Obs = std::ptr::null_mut();

unsafe fn alloc_guarded() -> *mut Guarded {
    alloc(Layout::new::<Guarded>()) as *mut Guarded
}

unsafe fn free_guarded(g: *mut Guarded) {
    dealloc(g as *mut u8, Layout::new::<Guarded>());
}

unsafe fn guard_set(g: *mut Guarded) {
    for i in 0..16 {
        std::ptr::write_volatile((*g).buf.as_mut_ptr().add(i), 0x41);
    }
    std::ptr::write_volatile(&mut (*g).canary, CANARY);
    std::ptr::write_volatile(&mut (*g).sentinel, SENTINEL);
    if !OBS.is_null() {
        (*OBS).canary_before = std::ptr::read_volatile(&(*g).canary);
        (*OBS).sentinel_before = std::ptr::read_volatile(&(*g).sentinel);
    }
}

unsafe fn guard_check(g: *mut Guarded) {
    if !OBS.is_null() {
        (*OBS).canary_after = std::ptr::read_volatile(&(*g).canary);
        (*OBS).sentinel_after = std::ptr::read_volatile(&(*g).sentinel);
    }
}

/* -- Probe implementations (all intentionally unsafe) ------------------- */

fn probe_use_after_free() {
    unsafe {
        let g = alloc_guarded();
        guard_set(g);
        free_guarded(g);
        let _x = std::ptr::read_volatile((*g).buf.as_ptr()); // USE AFTER FREE (read)
        guard_check(g);
    }
}

fn probe_double_free() {
    unsafe {
        let g = alloc_guarded();
        guard_set(g);
        free_guarded(g);
        free_guarded(g); // DOUBLE FREE
        guard_check(g);
    }
}

fn probe_buffer_overflow() {
    unsafe {
        let g = alloc_guarded();
        guard_set(g);
        let _x = std::ptr::read_volatile((*g).buf.as_ptr().add(200)); // OOB READ
        guard_check(g);
    }
}

fn probe_null_deref() {
    unsafe {
        let p: *const i32 = std::ptr::null();
        let _x = std::ptr::read_volatile(p); // NULL DEREFERENCE
    }
}

fn probe_integer_overflow() {
    unsafe {
        let g = alloc_guarded();
        guard_set(g);
        let a: i32 = i32::MAX;
        let _b = a.wrapping_add(1); // defined (no UB) -- observed survival
        let _c = a.unchecked_add(1); // UB path
        guard_check(g);
        free_guarded(g);
    }
}

fn probe_use_of_uninit() {
    unsafe {
        let g = alloc_guarded();
        guard_set(g);
        let x: i32 = std::mem::MaybeUninit::uninit().assume_init();
        let _y = std::ptr::read_volatile(&x); // read uninitialized memory
        guard_check(g);
        free_guarded(g);
    }
}

fn probe_type_confusion() {
    unsafe {
        let g = alloc_guarded();
        guard_set(g);
        let f: f32 = 3.14;
        let ip: *const i32 = &f as *const f32 as *const i32;
        let _confused = std::ptr::read_volatile(ip); // reinterpret bits
        guard_check(g);
        free_guarded(g);
    }
}

#[inline(never)]
fn probe_stack_overflow() {
    let dummy = [0u8; 4096];
    static DEPTH: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);
    DEPTH.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    std::hint::black_box(&dummy);
    probe_stack_overflow();
    std::hint::black_box(dummy[0]); // anti-TCO
}

fn probe_buffer_overflow_write() {
    unsafe {
        let g = alloc_guarded();
        guard_set(g);
        for i in 0..256isize {
            std::ptr::write_volatile((*g).buf.as_mut_ptr().offset(i), i as u8); // OOB WRITE
        }
        guard_check(g);
    }
}

fn probe_invalid_free() {
    unsafe {
        let mut g = Guarded { buf: [0; 16], canary: 0, sentinel: 0 };
        guard_set(&mut g);
        dealloc(&mut g as *mut Guarded as *mut u8, Layout::new::<Guarded>()); // INVALID FREE
        guard_check(&mut g);
    }
}

fn probe_division_by_zero() {
    unsafe {
        let g = alloc_guarded();
        guard_set(g);
        let z: i32 = std::ptr::read_volatile(&0i32);
        let _q = 1 / z; // DIVISION BY ZERO (Rust panics)
        guard_check(g);
        free_guarded(g);
    }
}

fn probe_invalid_pointer() {
    unsafe {
        let g = alloc_guarded();
        guard_set(g);
        let p = 0xdeadbeefusize as *mut i32;
        std::ptr::write_volatile(p, 1); // bogus non-null pointer
        guard_check(g);
    }
}

/* -- Probe metadata ------------------------------------------------------ */

static PROBE_NAMES: [&str; N_PROBES] = [
    "use-after-free", "double-free", "buffer-overflow", "null-deref",
    "integer-overflow", "use-of-uninit", "type-confusion", "stack-overflow",
    "buffer-overflow-write", "invalid-free", "division-by-zero", "invalid-pointer",
];
static PROBE_TRACKS: [&str; N_PROBES] = [
    "SAFE_SUBSET", "SAFE_SUBSET", "SAFE_SUBSET", "FAULT_CONTAINMENT",
    "UNSAFE_BOUNDARY", "SAFE_SUBSET", "UNSAFE_BOUNDARY", "FAULT_CONTAINMENT",
    "SAFE_SUBSET", "UNSAFE_BOUNDARY", "FAULT_CONTAINMENT", "UNSAFE_BOUNDARY",
];
static PROBE_FNS: [fn(); N_PROBES] = [
    probe_use_after_free, probe_double_free, probe_buffer_overflow, probe_null_deref,
    probe_integer_overflow, probe_use_of_uninit, probe_type_confusion, probe_stack_overflow,
    probe_buffer_overflow_write, probe_invalid_free, probe_division_by_zero, probe_invalid_pointer,
];

/* -- Isolation + classification ------------------------------------------ */

#[cfg(unix)]
fn run_isolated(f: fn()) -> (i32, Option<Obs>) {
    unsafe {
        let mut fds = [0i32; 2];
        if pipe(fds.as_mut_ptr()) != 0 {
            return (-1001, None);
        }
        // Flush before fork: a forked child must not inherit unflushed stdout,
        // otherwise every child re-emits the parent's buffer and corrupts the
        // JSON (observed while migrating this fixture).
        {
            use std::io::Write;
            let _ = std::io::stdout().flush();
        }
        let pid = fork();
        if pid == 0 {
            close(fds[0]);
            let mut obs = Obs::default();
            OBS = &mut obs;
            f();
            obs.attack_completed = 1;
            write(fds[1], &obs as *const Obs as *const u8, std::mem::size_of::<Obs>());
            close(fds[1]);
            std::process::exit(0);
        }
        close(fds[1]);
        let mut out = Obs::default();
        let n = read(fds[0], &mut out as *mut Obs as *mut u8, std::mem::size_of::<Obs>());
        close(fds[0]);
        let mut status: i32 = 0;
        waitpid(pid, &mut status, 0);
        let sig = status & 0x7f;
        if sig != 0 && sig != 0x7f {
            return (sig, None); // os crash
        }
        let code = (status >> 8) & 0xff;
        if code != 0 {
            return (-code, None); // runtime panic / non-zero exit
        }
        if n != std::mem::size_of::<Obs>() as isize {
            return (-1000, None); // exit 0 without observation
        }
        (0, Some(out))
    }
}

#[cfg(not(unix))]
fn run_isolated(_f: fn()) -> (i32, Option<Obs>) {
    (-1000, None)
}

struct Classified {
    outcome: &'static str,
    mechanism: String,
    error_detected: i32,
    survived: i32,
    corrupted: i32,
    canary_intact: i32,
    sentinel_intact: i32,
    has_obs: bool,
    score: i32,
    obs: Obs,
}

fn tb(v: i32) -> &'static str {
    if v < 0 { "null" } else if v > 0 { "true" } else { "false" }
}

fn classify(rc: i32, obs: Option<Obs>) -> Classified {
    let blank = Obs::default();
    let mut c = Classified {
        outcome: "INCONCLUSIVE",
        mechanism: String::new(),
        error_detected: -1,
        survived: -1,
        corrupted: -1,
        canary_intact: -1,
        sentinel_intact: -1,
        has_obs: false,
        score: -1,
        obs: blank,
    };
    if rc > 0 {
        c.outcome = "OS_CRASH";
        c.mechanism = format!("os_crash(signal {})", rc);
        c.error_detected = 1;
        c.survived = 0;
        c.corrupted = 0;
        c.score = 2;
        return c;
    }
    if rc < 0 && rc != -1000 {
        c.outcome = "RUNTIME_PANIC";
        c.mechanism = format!("runtime_panic(exit {})", -rc);
        c.error_detected = 1;
        c.survived = 0;
        c.corrupted = 0;
        c.score = 6;
        return c;
    }
    let o = match obs {
        Some(o) => o,
        None => {
            c.mechanism = "exit 0 without observation (unscored)".to_string();
            return c;
        }
    };
    c.has_obs = true;
    c.obs = o;
    let canary_mutated = o.canary_before != o.canary_after;
    let sentinel_mutated = o.sentinel_before != o.sentinel_after;
    c.canary_intact = if canary_mutated { 0 } else { 1 };
    c.sentinel_intact = if sentinel_mutated { 0 } else { 1 };
    c.error_detected = 0;
    c.survived = 1;
    if o.attack_completed != 1 {
        c.mechanism = "attack did not complete (unscored)".to_string();
        return c;
    }
    let corrupted = canary_mutated || sentinel_mutated;
    c.corrupted = if corrupted { 1 } else { 0 };
    if corrupted {
        c.outcome = "SILENT_FAILURE";
        c.mechanism = "silent(state corruption confirmed by canary/sentinel)".to_string();
        c.score = 0;
    } else {
        c.outcome = "SILENT_UB";
        c.mechanism = "silent(unreported UB; no corruption observed)".to_string();
        c.score = 0;
    }
    c
}

fn num_or_null_u32(v: u32) -> String {
    if v == 0 { "null".to_string() } else { v.to_string() }
}

fn num_or_null_u64(v: u64) -> String {
    if v == 0 { "null".to_string() } else { v.to_string() }
}

fn main() {
    // Build the whole report in memory and print it once, after every fork has
    // completed: stdout stays untouched across fork(), so no child can inherit
    // a partial buffer (see run_isolated).
    use std::fmt::Write as FmtWrite;
    let mut out = String::new();
    let _ = write!(out, "{{\"test\":\"t8-safety-probe\",\"language\":\"Rust\",\"schema_version\":\"2.0\",");
    let _ = write!(out, "\"note\":\"Each probe isolated in a forked child; canary/sentinel observations carried over a pipe; parent classifies from evidence.\",\"probes\":[");
    let mut total: i64 = 0;
    let mut scored: i32 = 0;
    for i in 0..N_PROBES {
        let (rc, obs) = run_isolated(PROBE_FNS[i]);
        let c = classify(rc, obs);
        if c.score >= 0 {
            total += c.score as i64;
            scored += 1;
        }
        if i > 0 {
            let _ = write!(out, ",");
        }
        let (cb, ca, sb, sa) = if c.has_obs {
            (
                num_or_null_u32(c.obs.canary_before),
                num_or_null_u32(c.obs.canary_after),
                num_or_null_u64(c.obs.sentinel_before),
                num_or_null_u64(c.obs.sentinel_after),
            )
        } else {
            ("null".to_string(), "null".to_string(), "null".to_string(), "null".to_string())
        };
        let attack = if c.has_obs { tb(c.obs.attack_completed) } else { "true" };
        let score = if c.score < 0 { "null".to_string() } else { c.score.to_string() };
        let _ = write!(
            out,
            "{{\"name\":\"{}\",\"track\":\"{}\",\"outcome_class\":\"{}\",\"mechanism\":\"{}\",\"error_detected\":{},\"program_survived\":{},\"state_corrupted\":{},\"canary_intact\":{},\"sentinel_intact\":{},\"canary_before\":{},\"canary_after\":{},\"sentinel_before\":{},\"sentinel_after\":{},\"attack_completed\":{},\"containment\":false,\"containment_note\":\"parent-observed execution\",\"score\":{}}}",
            PROBE_NAMES[i], PROBE_TRACKS[i], c.outcome, c.mechanism,
            tb(c.error_detected), tb(c.survived), tb(c.corrupted),
            tb(c.canary_intact), tb(c.sentinel_intact),
            cb, ca, sb, sa, attack, score
        );
    }
    let index = if scored > 0 { (total * 100 / (scored as i64 * 10)) as i32 } else { 0 };
    let _ = writeln!(out, "],\"safety_index\":{}}}", index);
    print!("{}", out);
}

