  while i < probe_count() {
    obs_paths[i] = self_path + ".probe" + int_to_string(i) + ".json";
    i = i + 1;
  }

  i = 0;
  while i < N_PROBES {
    var s = measure(i, self_path, obs_paths[i]);
    scores[i] = s;
    i = i + 1;
  }

  var total: Int = 0;
  var scored: Int = 0;
  var inconclusive: Int = 0;
  i = 0;
  while i < N_PROBES {
    if scores[i] >= 0 {
      total = total + scores[i];
