  io.println("[t8] XIOM safety probe (child-isolated, canary-checked, schema 2.0)");
  io.println("{");
  io.println("  \"test\": \"t8-safety-probe\",");
  io.println("  \"language\": \"XIOM\",");
  io.println("  \"schema_version\": \"2.0\",");
  io.println("  \"note\": \"Compiled with the harness arena flags (config languages.systems.xiom.compiler_flags). Each probe isolated in a child process with CANARY/SENTINEL integrity checks; an exit code of 0 without an observation is reported INCONCLUSIVE, never silent.\",");
  io.println("  \"probes\": [");
  i = 0;
  while i < N_PROBES {
    var outcome = outcome_of(scores[i], obs_paths[i]);
    var comma = ",";
    if i == N_PROBES - 1 {
      comma = "";
    }
    var score_str = "null";
    if scores[i] >= 0 { score_str = int_to_string(scores[i]); }
    var line = "    {\"name\": \"" + probe_name(i) + "\"";
    line = line + ", \"track\": \"" + probe_track(i) + "\"";
    line = line + ", \"outcome_class\": \"" + outcome + "\"";
    line = line + ", \"mechanism\": \"" + mechanism_of(outcome) + "\"";
    line = line + ", \"error_detected\": " + bool_str(error_detected_of(outcome));
    line = line + ", \"program_survived\": " + bool_str(survived_of(outcome));
    line = line + ", \"state_corrupted\": " + tri_str(state_tri(scores[i], obs_paths[i]));
    line = line + ", \"canary_intact\": " + tri_str(obs_flag(obs_paths[i], "canary_intact"));
    line = line + ", \"sentinel_intact\": " + tri_str(obs_flag(obs_paths[i], "sentinel_intact"));
    line = line + ", \"attack_completed\": " + tri_str(obs_flag(obs_paths[i], "attack_completed"));
    line = line + ", \"containment\": false";
    line = line + ", \"containment_note\": \"parent-observed child execution; process termination is not fault containment\"";
