// SPDX-License-Identifier: MIT OR Apache-2.0

const std = @import("std");

pub const SPSCQueue = struct {
    head: std.atomic.Value(usize),
    tail: std.atomic.Value(usize),
    capacity: usize,
    buffer: []i64,

    const Self = @This();

    pub fn init(allocator: std.mem.Allocator, capacity: usize) !*Self {
        const q = try allocator.create(Self);
        q.head = std.atomic.Value(usize).init(0);
        q.tail = std.atomic.Value(usize).init(0);
        q.capacity = capacity + 1;
        q.buffer = try allocator.alloc(i64, q.capacity);
        @memset(q.buffer, 0);
        return q;
    }

    pub fn deinit(self: *Self, allocator: std.mem.Allocator) void {
        allocator.free(self.buffer);
        allocator.destroy(self);
    }

    pub fn enqueue(self: *Self, val: i64) bool {
        const tail = self.tail.load(.acquire);
        const next = (tail + 1) % self.capacity;
        if (next == self.head.load(.acquire)) return false;
        self.buffer[tail] = val;
        self.tail.store(next, .release);
        return true;
    }

    pub fn dequeue(self: *Self) ?i64 {
        const head = self.head.load(.acquire);
        if (head == self.tail.load(.acquire)) return null;
        const val = self.buffer[head];
        self.head.store((head + 1) % self.capacity, .release);
        return val;
    }
};

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer {
        _ = gpa.deinit();
    }
    const allocator = gpa.allocator();

    const q = try SPSCQueue.init(allocator, 1000000);
    defer q.deinit(allocator);

    var i: i64 = 0;
    while (i < 1000000) : (i += 1) {
        _ = q.enqueue(i);
    }

    i = 0;
    while (i < 1000000) : (i += 1) {
        _ = q.dequeue();
    }

    std.debug.print("OK\n", .{});
}

