// Copyright (c) 2026 Eleftherios Notas and The XIOM Authors
// SPDX-License-Identifier: MIT OR Apache-2.0

// Reference implementation: Hot-Reload Module Loader (Zig)
// Systems Arena -- measures execution speed, memory usage, binary size.
//
// Real dynamic module loading through std.DynLib (libc dlopen/dlsym/dlclose;
// the arena build links libc explicitly): every cycle opens a shared library,
// resolves the exported function, calls it 100 times, then hot-reloads (a
// fresh open replaces the old handle) and unloads it. The workload is
// identical for every language: libc.so.6 / abs, 1000 cycles x 100 calls.

const std = @import("std");

const cycles: usize = 1000;
const calls_per_cycle: usize = 100;
const module_path = "libc.so.6";
const symbol_name = "abs";

const AbsFn = *const fn (c_int) callconv(.C) c_int;

pub fn main() !void {
    var timer = try std.time.Timer.start();
    var checksum: i64 = 0;

    var i: usize = 0;
    while (i < cycles) : (i += 1) {
        var lib = std.DynLib.open(module_path) catch return error.OpenFailed;
        const abs_fn = lib.lookup(AbsFn, symbol_name) orelse return error.SymbolNotFound;

        var j: usize = 0;
        while (j < calls_per_cycle) : (j += 1) {
            const arg: c_int = @intCast(@mod(i * 31 + j * 17, 1000) - 500);
            checksum += abs_fn(arg);
        }

        var fresh = std.DynLib.open(module_path) catch return error.ReloadFailed;
        lib.close();
        fresh.close();
    }

    const elapsed_ns = timer.read();
    const ms = @as(f64, @floatFromInt(elapsed_ns)) / 1_000_000.0;
    const out = std.io.getStdOut().writer();
    try out.print(
        "{{\"op\":\"hot-reload\",\"cycles\":{d},\"calls\":{d},\"checksum\":{d},\"time_ms\":{d:.2}}}\n",
        .{ cycles, cycles * calls_per_cycle, checksum, ms },
    );
}

