const std = @import("std");

const TcpHeader = struct {
    src_port: u16,
    dst_port: u16,
    seq_num: u32,
    ack_num: u32,
    data_offset: u4,
    reserved: u3,
    ns: u1,
    flags: u8,
    window: u16,
    checksum: u16,
    urgent_ptr: u16,
};

fn parsePacket(data: []const u8) !TcpHeader {
    if (data.len < 20) return error.BufferTooShort;
    return TcpHeader{
        .src_port = (@as(u16, data[0]) << 8) | data[1],
        .dst_port = (@as(u16, data[2]) << 8) | data[3],
        .seq_num = (@as(u32, data[4]) << 24) | (@as(u32, data[5]) << 16) | (@as(u32, data[6]) << 8) | data[7],
        .ack_num = (@as(u32, data[8]) << 24) | (@as(u32, data[9]) << 16) | (@as(u32, data[10]) << 8) | data[11],
        .data_offset = @as(u4, @truncate(data[12] >> 4)),
        .reserved = @as(u3, @truncate((data[12] >> 1) & 7)),
        .ns = @as(u1, @truncate(data[12] & 1)),
        .flags = data[13],
        .window = (@as(u16, data[14]) << 8) | data[15],
        .checksum = (@as(u16, data[16]) << 8) | data[17],
        .urgent_ptr = (@as(u16, data[18]) << 8) | data[19],
    };
}

fn computeChecksum(data: []const u8) u16 {
    var sum: u32 = 0;
    var i: usize = 0;
    while (i + 1 < data.len) : (i += 2) {
        sum += (@as(u16, data[i]) << 8) | data[i + 1];
    }
    if (data.len & 1 != 0) {
        sum += @as(u16, data[data.len - 1]) << 8;
    }
    while (sum >> 16 != 0) {
        sum = (sum & 0xFFFF) + (sum >> 16);
    }
    return @as(u16, @truncate(~sum));
}

pub fn main() !void {
    var packet: [40]u8 = [_]u8{0} ** 40;

    packet[0] = 0x1F;
    packet[1] = 0x90;
    packet[2] = 0x00;
    packet[3] = 0x50;
    packet[4] = 0x00;
    packet[5] = 0x00;
    packet[6] = 0x00;
    packet[7] = 0x01;
    packet[12] = 0x50;
    packet[13] = 0x02;
    packet[14] = 0x7F;
    packet[15] = 0xFF;

    var i: usize = 0;
    while (i < 1_000_000) : (i += 1) {
        packet[4] = @as(u8, @truncate(i >> 24));
        packet[5] = @as(u8, @truncate(i >> 16));
        packet[6] = @as(u8, @truncate(i >> 8));
        packet[7] = @as(u8, @truncate(i));
        const csum = computeChecksum(packet[0..20]);
        packet[16] = @as(u8, @truncate(csum >> 8));
        packet[17] = @as(u8, @truncate(csum));
        _ = try parsePacket(packet[0..20]);
    }

    std.debug.print("OK\n", .{});
}

