// Copyright (c) 2026 Eleftherios Notas and The XIOM Authors
// SPDX-License-Identifier: MIT OR Apache-2.0

package main

import (
	"fmt"
	"unsafe"
)

const (
	POOL_SIZE = 1024 * 1024
	MIN_BLOCK = 64
	MAX_ORDER = 14
	N         = 10000
)

type block struct {
	free  bool
	_     [7]byte
	order int
	next  *block
}

var (
	pool      [POOL_SIZE]byte
	freeLists [MAX_ORDER + 1]*block
)

func orderForSize(size int) int {
	blockSize := int(unsafe.Sizeof(block{}))
	bsize := MIN_BLOCK
	order := 0
	for bsize < size+blockSize {
		bsize <<= 1
		order++
	}
	if order > MAX_ORDER {
		return MAX_ORDER
	}
	return order
}

func blockSizeForOrder(order int) int {
	return MIN_BLOCK << order
}

func blockAt(off uintptr) *block {
	return (*block)(unsafe.Pointer(&pool[off]))
}

func splitBlock(order int) *block {
	if order > MAX_ORDER {
		return nil
	}
	if freeLists[order] != nil {
		b := freeLists[order]
		freeLists[order] = b.next
		b.free = false
		return b
	}
	if order == MAX_ORDER {
		return nil
	}
	bigger := splitBlock(order + 1)
	if bigger == nil {
		return nil
	}
	half := uintptr(blockSizeForOrder(order))
	off := uintptr(unsafe.Pointer(bigger)) - uintptr(unsafe.Pointer(&pool[0]))
	buddyOff := off + half
	buddy := blockAt(buddyOff)
	buddy.free = true
	buddy.order = order
	buddy.next = freeLists[order]
	freeLists[order] = buddy
	bigger.free = false
	bigger.order = order
	return bigger
}

func buddyInit() {
	for i := range pool {
		pool[i] = 0
	}
	for i := range freeLists {
		freeLists[i] = nil
	}
	root := blockAt(0)
	root.free = true
	root.order = MAX_ORDER
	root.next = nil
	freeLists[MAX_ORDER] = root
}

func buddyAlloc(size int) unsafe.Pointer {
	if size == 0 {
		return nil
	}
	order := orderForSize(size)
	b := splitBlock(order)
	if b == nil {
		return nil
	}
	return unsafe.Pointer(uintptr(unsafe.Pointer(b)) + unsafe.Sizeof(block{}))
}

func buddyFree(ptr unsafe.Pointer) {
	if ptr == nil {
		return
	}
	bsize := unsafe.Sizeof(block{})
	b := (*block)(unsafe.Pointer(uintptr(ptr) - bsize))
	b.free = true
	for b.order < MAX_ORDER {
		orderSize := uintptr(blockSizeForOrder(b.order))
		addr := uintptr(unsafe.Pointer(b)) - uintptr(unsafe.Pointer(&pool[0]))
		buddyAddr := addr ^ orderSize
		if buddyAddr+orderSize > POOL_SIZE {
			break
		}
		buddy := blockAt(buddyAddr)
		if !buddy.free || buddy.order != b.order {
			break
		}
		prev := &freeLists[b.order]
		for *prev != nil && *prev != buddy {
			prev = &(*prev).next
		}
		if *prev != nil {
			*prev = buddy.next
		}
		if buddyAddr < addr {
			b = buddy
		}
		b.order++
	}
	b.next = freeLists[b.order]
	freeLists[b.order] = b
}

func main() {
	buddyInit()
	ptrs := make([]unsafe.Pointer, N)
	for i := 0; i < N; i++ {
		sz := 64 + (i*997)%4096
		ptrs[i] = buddyAlloc(sz)
	}
	for i := 0; i < N; i += 2 {
		buddyFree(ptrs[i])
	}
	for i := 0; i < N; i += 2 {
		sz := 128 + (i*503)%2048
		ptrs[i] = buddyAlloc(sz)
	}
	for i := 0; i < N; i++ {
		buddyFree(ptrs[i])
	}
	fmt.Println("OK")
}

