package main

import (
	"fmt"
	"sync/atomic"
)

type SPSCQueue struct {
	head     atomic.Uint64
	tail     atomic.Uint64
	capacity uint64
	buffer   []int64
}

func queueNew(capacity uint64) *SPSCQueue {
	q := &SPSCQueue{
		capacity: capacity + 1,
		buffer:   make([]int64, capacity+1),
	}
	q.head.Store(0)
	q.tail.Store(0)
	return q
}

func (q *SPSCQueue) enqueue(val int64) bool {
	tail := q.tail.Load()
	next := (tail + 1) % q.capacity
	if next == q.head.Load() {
		return false
	}
	q.buffer[tail] = val
	q.tail.Store(next)
	return true
}

func (q *SPSCQueue) dequeue() (int64, bool) {
	head := q.head.Load()
	if head == q.tail.Load() {
		return 0, false
	}
	val := q.buffer[head]
	q.head.Store((head + 1) % q.capacity)
	return val, true
}

func main() {
	q := queueNew(1000000)
	for i := int64(0); i < 1000000; i++ {
		q.enqueue(i)
	}
	for i := 0; i < 1000000; i++ {
		q.dequeue()
	}
	fmt.Println("OK")
}

