// Copyright (c) 2026 Eleftherios Notas and The XIOM Authors
// SPDX-License-Identifier: MIT OR Apache-2.0

/*
 * Reference implementation: Hot-Reload Module Loader (Go)
 * Systems Arena -- measures execution speed, memory usage, binary size.
 *
 * Real dynamic module loading through cgo (CGO_ENABLED=1 + gcc in the image):
 * every cycle opens a shared library (dlopen), resolves the exported function
 * (dlsym), calls it 100 times, then hot-reloads (a fresh dlopen replaces the
 * old handle) and unloads it (dlclose). The workload is identical for every
 * language: libc.so.6 / abs, 1000 cycles x 100 calls, deterministic args.
 */

package main

/*
#cgo LDFLAGS: -ldl
#include <dlfcn.h>
#include <stdlib.h>

static int xiom_abs_call(void *fn, int x) {
    return ((int (*)(int))fn)(x);
}
*/
import "C"

import (
	"fmt"
	"time"
	"unsafe"
)

const (
	cycles        = 1000
	callsPerCycle = 100
)

func main() {
	path := C.CString("libc.so.6")
	defer C.free(unsafe.Pointer(path))
	symbol := C.CString("abs")
	defer C.free(unsafe.Pointer(symbol))

	start := time.Now()
	var checksum int64

	for i := 0; i < cycles; i++ {
		handle := C.dlopen(path, C.RTLD_NOW)
		if handle == nil {
			panic("dlopen failed")
		}
		address := C.dlsym(handle, symbol)
		if address == nil {
			C.dlclose(handle)
			panic("dlsym failed")
		}
		for j := 0; j < callsPerCycle; j++ {
			arg := C.int((i*31 + j*17) % 1000 - 500)
			checksum += int64(C.xiom_abs_call(address, arg))
		}
		fresh := C.dlopen(path, C.RTLD_NOW)
		if fresh == nil {
			C.dlclose(handle)
			panic("reload dlopen failed")
		}
		C.dlclose(handle)
		C.dlclose(fresh)
	}

	ms := float64(time.Since(start).Nanoseconds()) / 1e6
	fmt.Printf("{\"op\":\"hot-reload\",\"cycles\":%d,\"calls\":%d,\"checksum\":%d,\"time_ms\":%.2f}\n",
		cycles, cycles*callsPerCycle, checksum, ms)
}

