package main

import (
	"encoding/binary"
	"fmt"
	"time"
)

type TcpHeader struct {
	SrcPort    uint16
	DstPort    uint16
	SeqNum     uint32
	AckNum     uint32
	DataOffset uint8
	Reserved   uint8
	NS         uint8
	Flags      uint8
	Window     uint16
	Checksum   uint16
	UrgentPtr  uint16
}

func parsePacket(data []byte, hdr *TcpHeader) int {
	if len(data) < 20 {
		return -1
	}
	hdr.SrcPort = binary.BigEndian.Uint16(data[0:2])
	hdr.DstPort = binary.BigEndian.Uint16(data[2:4])
	hdr.SeqNum = binary.BigEndian.Uint32(data[4:8])
	hdr.AckNum = binary.BigEndian.Uint32(data[8:12])
	b := data[12]
	hdr.DataOffset = b >> 4
	hdr.Reserved = (b >> 1) & 0x7
	hdr.NS = b & 0x1
	hdr.Flags = data[13]
	hdr.Window = binary.BigEndian.Uint16(data[14:16])
	hdr.Checksum = binary.BigEndian.Uint16(data[16:18])
	hdr.UrgentPtr = binary.BigEndian.Uint16(data[18:20])
	return 0
}

func computeChecksum(data []byte) uint16 {
	var sum uint32
	n := len(data) & ^1
	for i := 0; i < n; i += 2 {
		sum += uint32(data[i])<<8 | uint32(data[i+1])
	}
	if len(data)&1 != 0 {
		sum += uint32(data[len(data)-1]) << 8
	}
	for sum>>16 != 0 {
		sum = (sum & 0xFFFF) + (sum >> 16)
	}
	return uint16(^sum)
}

func main() {
	start := time.Now()
	packet := [40]byte{
		0x1F, 0x90, 0x00, 0x50, 0x00, 0x00, 0x00, 0x01,
		0x00, 0x00, 0x00, 0x00, 0x50, 0x02, 0x7F, 0xFF,
		0x00, 0x00, 0x00, 0x00,
	}

	var hdr TcpHeader
	for i := 0; i < 1000000; i++ {
		packet[4] = byte(i >> 24)
		packet[5] = byte(i >> 16)
		packet[6] = byte(i >> 8)
		packet[7] = byte(i)
		csum := computeChecksum(packet[:20])
		packet[16] = byte(csum >> 8)
		packet[17] = byte(csum)
		parsePacket(packet[:20], &hdr)
	}

	elapsed := float64(time.Since(start).Microseconds()) / 1000.0
	pps := 0.0
	if elapsed > 0 {
		pps = 1000000000.0 / elapsed
	}
	fmt.Printf("{\"op\":\"packet-parse\",\"packets\":1000000,\"time_ms\":%.2f,\"pps\":%.0f}\n", elapsed, pps)
}

