type BTreeEntry struct {
	key         int64
	value       int64
	childOffset int64
}

type BTreeNode struct {
	numKeys    int
	isLeaf     int
	parentOff  int64
	entries    [MAX_KEYS]BTreeEntry
	children   [MAX_CHILD]int64
}

var (
	nodePool [NODE_POOL]BTreeNode
	poolIdx  int
)

func allocNode() *BTreeNode {
	if poolIdx >= NODE_POOL {
		return nil
	}
	nodePool[poolIdx] = BTreeNode{isLeaf: 1}
	n := &nodePool[poolIdx]
	poolIdx++
	return n
}

func btreeSearch(node *BTreeNode, key int64) (int64, bool) {
	i := 0
	for i < node.numKeys && key > node.entries[i].key {
		i++
	}
	if i < node.numKeys && key == node.entries[i].key {
		return node.entries[i].value, true
	}
	return 0, false
}

func btreeInsertNonfull(node *BTreeNode, key, value int64) bool {
	if node.numKeys >= MAX_KEYS {
		return false
	}
	i := node.numKeys - 1
	for i >= 0 && key < node.entries[i].key {
		node.entries[i+1] = node.entries[i]
		i--
	}
	node.entries[i+1].key = key
	node.entries[i+1].value = value
	node.numKeys++
	return true
}

func main() {
	start := time.Now()
	root := allocNode()

	for i := int64(0); i < 50000; i++ {
		btreeInsertNonfull(root, i*3, i*7)
	}

	found := 0
	for i := int64(0); i < 20000; i++ {
		if _, ok := btreeSearch(root, i*5); ok {
			found++
		}
	}

	elapsed := float64(time.Since(start).Microseconds()) / 1000.0
	fmt.Printf("{\"op\":\"btree\",\"inserts\":50000,\"searches\":20000,\"found\":%d,\"time_ms\":%.2f}\n", found, elapsed)
}

