-- Copyright (c) 2026 Eleftherios Notas and The XIOM Authors
-- SPDX-License-Identifier: MIT OR Apache-2.0

-- Reference implementation: Buddy Memory Allocator (Ada 2012)
-- Systems Arena — measures raw execution speed, memory usage, binary size.
-- Compile: gnatmake -O2 -o t1-allocator t1-allocator.adb -cargs -gnatQ

with Ada.Text_IO; use Ada.Text_IO;
with System;
with System.Storage_Elements;
with Ada.Unchecked_Conversion;

procedure Main is
    use System;
    use System.Storage_Elements;

    Pool_Size : constant := 1024 * 1024;
    Min_Block : constant := 64;
    Max_Order : constant := 14;

    type Block;
    type Block_Ptr is access all Block;
    type Block is record
        Free : Boolean := False;
        Ord  : Integer;
        Next : Block_Ptr;
    end record;

    function To_Block_Ptr is new Ada.Unchecked_Conversion (Address, Block_Ptr);
    function To_Addr     is new Ada.Unchecked_Conversion (Block_Ptr, Address);

    Block_Header_Size : constant Storage_Count :=
      Storage_Count ((Block'Size + System.Storage_Unit - 1) / System.Storage_Unit);

    type Pool_Array is array (1 .. Pool_Size) of Storage_Element;
    Pool : Pool_Array := (others => 0)
      with Alignment => 64;

    type Free_List_Array is array (0 .. Max_Order) of Block_Ptr;
    Free_Lists : Free_List_Array := (others => null);
    Initialized : Boolean := False;

    function Order_For_Size (Sz : Storage_Count) return Integer is
        Block_Size : Storage_Count := Storage_Count (Min_Block);
        Ord : Integer := 0;
    begin
        while Block_Size < Sz + Block_Header_Size loop
            Block_Size := Block_Size * 2;
            Ord := Ord + 1;
        end loop;
        if Ord > Max_Order then
            return Max_Order;
        end if;
        return Ord;
    end Order_For_Size;

    function Block_Size_For_Order (Ord : Integer) return Storage_Count is
    begin
        return Storage_Count (Min_Block) * Storage_Count (2 ** Ord);
    end Block_Size_For_Order;

    function Pool_Base return Address is
    begin
        return Pool (Pool'First)'Address;
    end Pool_Base;

    procedure Init is
        Root : Block_Ptr;
    begin
        if Initialized then
            return;
        end if;
        Pool := (others => 0);
        Free_Lists := (others => null);
        Root := To_Block_Ptr (Pool_Base);
        Root.Free := True;
        Root.Ord := Max_Order;
        Root.Next := null;
        Free_Lists (Max_Order) := Root;
        Initialized := True;
    end Init;

    function Split_Block (Ord : Integer) return Block_Ptr is
        B : Block_Ptr;
        Bigger : Block_Ptr;
        Half : Storage_Count;
        Buddy : Block_Ptr;
    begin
        if Ord > Max_Order then
            return null;
        end if;
        if Free_Lists (Ord) /= null then
            B := Free_Lists (Ord);
            Free_Lists (Ord) := B.Next;
            B.Free := False;
            return B;
        end if;
        if Ord = Max_Order then
            return null;
        end if;
        Bigger := Split_Block (Ord + 1);
        if Bigger = null then
            return null;
        end if;
        Half := Block_Size_For_Order (Ord);
        Buddy := To_Block_Ptr (To_Addr (Bigger) + Half);
        Buddy.Free := True;
        Buddy.Ord := Ord;
        Buddy.Next := Free_Lists (Ord);
        Free_Lists (Ord) := Buddy;
        Bigger.Free := False;
        Bigger.Ord := Ord;
        return Bigger;
    end Split_Block;

    function Alloc (Sz : Storage_Count) return Address is
        Ord : Integer;
        B : Block_Ptr;
    begin
        if not Initialized then
            Init;
        end if;
        if Sz = 0 then
            return Null_Address;
        end if;
        Ord := Order_For_Size (Sz);
        B := Split_Block (Ord);
        if B = null then
            return Null_Address;
        end if;
        return To_Addr (B) + Block_Header_Size;
    end Alloc;

    procedure Free (Ptr : Address) is
        B : Block_Ptr;
        Bsize : Storage_Count;
        Addr_Int : Integer_Address;
        Buddy_Addr_Int : Integer_Address;
        Buddy : Block_Ptr;
        Prev : Block_Ptr;
        Curr : Block_Ptr;
    begin
        if Ptr = Null_Address then
            return;
        end if;
        B := To_Block_Ptr (Ptr - Block_Header_Size);
        if B.Free then
            return;
        end if;
        B.Free := True;

        while B.Ord < Max_Order loop
            Bsize := Block_Size_For_Order (B.Ord);
            Addr_Int := To_Integer (To_Addr (B)) - To_Integer (Pool_Base);
            Buddy_Addr_Int := Addr_Int xor Integer_Address (Bsize);
            if Buddy_Addr_Int + Integer_Address (Bsize) > Integer_Address (Pool_Size) then
                exit;
            end if;
            Buddy := To_Block_Ptr (To_Address (To_Integer (Pool_Base) + Buddy_Addr_Int));
            if not Buddy.Free or else Buddy.Ord /= B.Ord then
                exit;
            end if;

            if Free_Lists (B.Ord) = Buddy then
                Free_Lists (B.Ord) := Buddy.Next;
            else
                Prev := Free_Lists (B.Ord);
                while Prev /= null and then Prev.Next /= Buddy loop
                    Prev := Prev.Next;
                end loop;
                if Prev /= null then
                    Prev.Next := Buddy.Next;
                end if;
            end if;

            if Addr_Int > Buddy_Addr_Int then
                B := Buddy;
            end if;
            B.Ord := B.Ord + 1;
        end loop;

        B.Next := Free_Lists (B.Ord);
        Free_Lists (B.Ord) := B;
    end Free;

    N : constant := 10000;
    type Ptr_Array is array (1 .. N) of Address;
    Ptrs : Ptr_Array := (others => Null_Address);
    Sz : Storage_Count;
begin
    Init;

    for I in 1 .. N loop
        Sz := Storage_Count (64 + ((I - 1) * 997) mod 4096);
        Ptrs (I) := Alloc (Sz);
    end loop;

    for I in 1 .. N loop
        if I mod 2 = 0 then
            Free (Ptrs (I));
            Ptrs (I) := Null_Address;
        end if;
    end loop;

    for I in 1 .. N loop
        if I mod 2 = 0 then
            Sz := Storage_Count (128 + ((I - 1) * 503) mod 2048);
            Ptrs (I) := Alloc (Sz);
        end if;
    end loop;

    for I in 1 .. N loop
        Free (Ptrs (I));
    end loop;

    Put_Line ("OK");
end Main;

