-- Copyright (c) 2026 Eleftherios Notas and The XIOM Authors
-- SPDX-License-Identifier: MIT OR Apache-2.0

-- Reference implementation: SPSC Concurrent Queue (Ada 2012)
-- Systems Arena — ring buffer queue with atomic head/tail.
-- Compile: gnatmake -O2 -o t2-queue t2-queue.adb -cargs -gnatQ

with Ada.Text_IO; use Ada.Text_IO;

procedure Main is
    Capacity : constant Integer := 1_000_000 + 1;
    type Buffer_Array is array (1 .. Capacity) of Long_Long_Integer;

    Buffer : Buffer_Array := (others => 0);
    Head   : Integer := 1;
    Tail   : Integer := 1;
    pragma Atomic (Head);
    pragma Atomic (Tail);

    function Enqueue (Val : Long_Long_Integer) return Boolean is
        Next : Integer;
    begin
        Next := Tail mod Capacity + 1;
        if Next = Head then
            return False;
        end if;
        Buffer (Tail) := Val;
        Tail := Next;
        return True;
    end Enqueue;

    function Dequeue (Val : out Long_Long_Integer) return Boolean is
    begin
        if Head = Tail then
            return False;
        end if;
        Val := Buffer (Head);
        Head := Head mod Capacity + 1;
        return True;
    end Dequeue;

    V  : Long_Long_Integer;
    Ok : Boolean;
begin
    for I in 0 .. 999_999 loop
        Ok := Enqueue (Long_Long_Integer (I));
        if not Ok then
            Put_Line ("ERROR: enqueue failed");
            return;
        end if;
    end loop;

    for I in 0 .. 999_999 loop
        Ok := Dequeue (V);
        if not Ok then
            Put_Line ("ERROR: dequeue failed");
            return;
        end if;
    end loop;

    Put_Line ("OK");
end Main;

