-- Reference implementation: Hot-Reload Module Loader (Ada 2012)
-- Systems Arena -- measures execution speed, memory usage, binary size.
--
-- Real dynamic module loading through C dlopen/dlsym/dlclose imports: every
-- cycle opens a shared library, resolves the exported function, calls it 100
-- times, then hot-reloads (a fresh dlopen replaces the old handle) and
-- unloads it. The workload is identical for every language: libc.so.6 / abs,
-- 1000 cycles x 100 calls, deterministic arguments.

with Ada.Calendar;
with Ada.Text_IO; use Ada.Text_IO;
with Interfaces.C; use Interfaces.C;
with Interfaces.C.Strings;
with System;
with Ada.Unchecked_Conversion;

procedure T3_Hot_Reload is
   use type System.Address;
   use type Ada.Calendar.Time;

   function C_Dlopen (Path : Interfaces.C.Strings.chars_ptr; Flags : int) return System.Address;
   pragma Import (C, C_Dlopen, "dlopen");

   function C_Dlsym (Handle : System.Address; Name : Interfaces.C.Strings.chars_ptr) return System.Address;
   pragma Import (C, C_Dlsym, "dlsym");

   procedure C_Dlclose (Handle : System.Address);
   pragma Import (C, C_Dlclose, "dlclose");

   type Abs_Func is access function (X : int) return int;
   function To_Abs_Func is new Ada.Unchecked_Conversion (System.Address, Abs_Func);

   RTLD_NOW        : constant int := 2;
   Cycles          : constant := 1000;
   Calls_Per_Cycle : constant := 100;

   Path_Ptr : Interfaces.C.Strings.chars_ptr := Interfaces.C.Strings.New_String ("libc.so.6");
   Sym_Ptr  : Interfaces.C.Strings.chars_ptr := Interfaces.C.Strings.New_String ("abs");

   Start    : constant Ada.Calendar.Time := Ada.Calendar.Clock;
   Checksum : Long_Long_Integer := 0;
begin
   for I in 0 .. Cycles - 1 loop
      declare
         Handle : System.Address;
         Fresh  : System.Address;
         Func   : Abs_Func;
      begin
         Handle := C_Dlopen (Path_Ptr, RTLD_NOW);
         if Handle = System.Null_Address then
            Put_Line ("dlopen failed");
            return;
         end if;
         Func := To_Abs_Func (C_Dlsym (Handle, Sym_Ptr));
         for J in 0 .. Calls_Per_Cycle - 1 loop
            declare
               Arg : constant int := int ((I * 31 + J * 17) mod 1000 - 500);
            begin
               Checksum := Checksum + Long_Long_Integer (Func (Arg));
            end;
         end loop;
         Fresh := C_Dlopen (Path_Ptr, RTLD_NOW);
         if Fresh = System.Null_Address then
            Put_Line ("reload dlopen failed");
            C_Dlclose (Handle);
            return;
         end if;
         C_Dlclose (Handle);
         C_Dlclose (Fresh);
      end;
   end loop;

   declare
      Elapsed_Ms : constant Long_Long_Integer :=
        Long_Long_Integer ((Ada.Calendar.Clock - Start) * 1000.0);
   begin
      Put_Line ("{""op"":""hot-reload"",""cycles"":" & Integer'Image (Cycles)
                & ",""calls"":" & Integer'Image (Cycles * Calls_Per_Cycle)
                & ",""checksum"":" & Long_Long_Integer'Image (Checksum)
                & ",""time_ms"":" & Long_Long_Integer'Image (Elapsed_Ms) & "}");
   end;

   Interfaces.C.Strings.Free (Path_Ptr);
   Interfaces.C.Strings.Free (Sym_Ptr);
end T3_Hot_Reload;

